```js
// npm install unicode-fallback
import { getFallback } from 'unicode-fallback';

/**
 * Returns an emoji string that is safe for older terminals.
 * If the terminal cannot render the emoji, a fallback string is returned.
 *
 * @param {string} emoji - The Unicode emoji to display.
 * @returns {string} - The original emoji or its fallback.
 */
export function safeEmoji(emoji) {
  const fallback = getFallback(emoji);
  return fallback || emoji;
}

/**
 * Example: Render an emoji in the DOM with a fallback.
 *
 * @param {HTMLElement} container - The element to append the emoji to.
 * @param {string} emoji - The Unicode emoji to display.
 */
export function renderEmoji(container, emoji) {
  const span = document.createElement('span');
  span.textContent = safeEmoji(emoji);
  container.appendChild(span);
}

// Usage
const container = document.getElementById('emoji-container');
renderEmoji(container, '🏳️‍🌈'); // rainbow flag
renderEmoji(container, '🧑🏽‍🚀'); // astronaut with medium skin tone
