// npm install spdx-expression-parser
const spdx = require('spdx-expression-parser');

/**
 * Takes an SPDX expression string, parses it, and returns a corrected (canonical)
 * version of the expression. If the input is invalid, an error is thrown.
 *
 * @param {string} exprStr - The SPDX expression to correct.
 * @returns {string} The canonical SPDX expression.
 */
function correctSpdxExpression(exprStr) {
  // Parse the expression into an AST
  const ast = spdx.parse(exprStr);

  // The AST has a toString() method that outputs a canonical form
  return ast.toString();
}

// Example usage:
try {
  const raw = 'MIT OR (Apache-2.0 AND GPL-2.0)';
  const corrected = correctSpdxExpression(raw);
  console.log('Corrected expression:', corrected);
} catch (err) {
  console.error('Invalid SPDX expression:', err.message);
}
```

```js
// SPDX expression parser using spdx-expression-evaluator
const spdx = require('spdx-expression-evaluator');

/**
 * Parses an SPDX license expression and returns a standardized AST.
 *
 * @param {string} exprStr - SPDX license expression (e.g., "MIT OR GPL-2.0-only").
 * @returns {object} Standardized AST with nodes:
 *   - { type: 'LICENSE', license: 'MIT' }
 *   - { type: 'AND' | 'OR' | 'NOT', operands: [...] }  // operands is an array for AND/OR, single element for NOT
 * @throws {Error} If the expression cannot be parsed.
 */
function parseSpdxExpression(exprStr) {
  try {
    const ast = spdx.parse(exprStr);

    const walk = node => {
      switch (node.type) {
        case 'license':
          return { type: 'LICENSE', license: node.license };
        case 'AND':
        case 'OR':
          return {
            type: node.type,
            operands: node.operands.map(walk),
          };
        case 'NOT':
          return {
            type: 'NOT',
            operands: [walk(node.operand)],
          };
        default:
          throw new Error(`Unsupported node type: ${node.type}`);
      }
    };

    return walk(ast);
  } catch (err) {
    throw new Error(`Failed to parse SPDX expression: ${err.message}`);
  }
}

module.exports = { parseSpdxExpression };
```

