```js
// Assumes filenoise is available as a global (e.g. via <script src="filenoise.min.js"></script>)
// or imported as an ES module: import filenoise from 'filenoise';

function toUint8Array(input) {
  if (input instanceof Uint8Array) return input;
  if (input instanceof ArrayBuffer) return new Uint8Array(input);
  if (Buffer.isBuffer(input)) return new Uint8Array(input);
  throw new TypeError('Unsupported input type');
}

function readAsArrayBuffer(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = reject;
    reader.readAsArrayBuffer(blob);
  });
}

export async function detectFileType(data) {
  // Convert input to Uint8Array
  const uint8 = toUint8Array(data);

  // Create a Blob from the Uint8Array
  const blob = new Blob([uint8]);

  // Read the Blob as an ArrayBuffer using FileReader
  const arrayBuffer = await readAsArrayBuffer(blob);

  // Use filenoise to detect the file type
  return new Promise((resolve, reject) => {
    filenoise.detect(arrayBuffer, (err, result) => {
      if (err) return reject(err);
      resolve(result); // e.g., { mime: 'image/png', ext: 'png', type: 'image' }
    });
  });
}
```

```js
// cssModuleExtractor.js
import fs from 'fs';
import path from 'path';
import cssModulesTransform from 'css-modules-transform';

/**
 * Reads a CSS file, transforms it with CSS‑Modules, writes the transformed CSS
 * and generates a JS module that imports the CSS and exports the class map.
 *
 * @param {string} inputCssPath  Path to the source CSS file
 * @param {string} outputJsPath  Path where the JS module will be written
 */
export function extractCssModule(inputCssPath, outputJsPath) {
  const css = fs.readFileSync(inputCssPath, 'utf8');

  const { css: transformedCss, exports } = cssModulesTransform(css, {
    generateScopedName: '[name]__[local]___[hash:base64:5]',
  });

  // Write the transformed CSS
  const cssOutPath = outputJsPath.replace(/\.js$/, '.css');
  fs.writeFileSync(cssOutPath, transformedCss, 'utf8');

  // Generate a JS module that imports the CSS and exports the mapping
  const jsContent = `
import styles from './${path.basename(cssOutPath)}';
export default styles;
`;
  fs.writeFileSync(outputJsPath, jsContent, 'utf8');
}
```

