```js
// Requires Node.js and the csstria package:
//   npm install csstria
const fs = require('fs').promises;
const csstria = require('csstria');

// List of simple hack patterns to filter out
const hackSelectors = [
  /^(\*|html > \*|html > body|body:before|body:after)/i, // common selector hacks
];
const hackProperties = [
  /^(\*|_)/i,          // leading * or _ in property names
  /^\/\*/,             // commented out declarations
];

// Helper to determine if a selector is a hack
function isHackSelector(selector) {
  return hackSelectors.some((re) => re.test(selector));
}

// Helper to determine if a declaration is a hack
function isHackProperty(property) {
  return hackProperties.some((re) => re.test(property));
}

// Main function
async function cleanCss(inputPath, outputPath) {
  const css = await fs.readFile(inputPath, 'utf8');
  const ast = csstria.parse(css);

  // Filter out hack rules/declarations
  ast.rules = ast.rules.filter((rule) => {
    // Skip non-style rules (e.g., @media, @keyframes)
    if (rule.type !== 'style') return true;

    // Remove hack selectors
    if (isHackSelector(rule.selector)) return false;

    // Filter declarations
    rule.declarations = rule.declarations.filter((decl) => {
      return !isHackProperty(decl.property);
    });

    // If no declarations left, drop the rule
    return rule.declarations.length > 0;
  });

  const cleanedCss = csstria.stringify(ast);
  await fs.writeFile(outputPath, cleanedCss, 'utf8');
  console.log(`Cleaned CSS written to ${outputPath}`);
}

// Example usage:
// cleanCss('input.css', 'output.css').catch(console.error);
```

