const remarkParser = require('remark-parser');

function remarkParsePlugin() {
  return (processor) => {
    // Override the processor's parse method
    processor.parse = (markdown) => {
      // Parse the Markdown string into an AST
      const tree = remarkParser.parse(markdown);
      // Pass the AST to Remark for further processing
      return processor.runSync(tree);
    };
  };
}

module.exports = remarkParsePlugin;
