```js
// Requires Streams3 (npm install streams3)
const streams3 = require('streams3');
const { Duplex } = require('stream');

/**
 * Creates a duplex stream that forwards data between a readable and a writable stream.
 *
 * @param {Readable} readable - The readable side of the duplex.
 * @param {Writable} writable - The writable side of the duplex.
 * @returns {Duplex} A duplex stream that pipes readable → writable and writable → readable.
 */
function createDuplexer(readable, writable) {
  // Use Streams3's duplexer helper to combine the streams.
  return streams3.duplexer(readable, writable);
}

// Example usage:
const { Readable, Writable } = require('stream');

// A simple readable that emits numbers 1-5
const readable = Readable.from([1, 2, 3, 4, 5]);

// A writable that logs received data
const writable = new Writable({
  write(chunk, encoding, callback) {
    console.log('Writable received:', chunk.toString());
    callback();
  }
});

const duplex = createDuplexer(readable, writable);

// Pipe the duplex to itself to demonstrate round‑trip (optional)
duplex.on('data', (chunk) => {
  console.log('Duplex output:', chunk.toString());
});

duplex.on('end', () => console.log('Duplex finished'));

// Start the flow
readable.pipe(duplex);
writable.on('finish', () => duplex.end());
