```js
// npm install javascript-evaluate
import evaluate from 'javascript-evaluate';

/**
 * Parses a string expression into a number.
 *
 * @param {string} expr          The expression to evaluate.
 * @param {Object} [config={}]   Optional configuration.
 * @param {boolean} [config.allowDecimal=true]   Allow decimal points.
 * @param {boolean} [config.allowNegative=true]  Allow negative numbers.
 * @param {boolean} [config.allowExponent=true]  Allow scientific notation.
 * @param {boolean} [config.allowParentheses=true] Allow parentheses.
 * @param {string[]} [config.allowOperators=['+','-','*','/','%']] Allowed operators.
 * @returns {number|null} The evaluated number, or null if parsing fails.
 */
export function parseNumberFromString(expr, config = {}) {
  const {
    allowDecimal = true,
    allowNegative = true,
    allowExponent = true,
    allowParentheses = true,
    allowOperators = ['+', '-', '*', '/', '%'],
  } = config;

  // Build a set of allowed characters
  const allowedChars = new Set('0123456789');
  if (allowDecimal) allowedChars.add('.');
  if (allowNegative) allowedChars.add('-');
  if (allowExponent) allowedChars.add('e');
  if (allowParentheses) {
    allowedChars.add('(');
    allowedChars.add(')');
  }
  allowOperators.forEach(op => allowedChars.add(op));

  // Quick sanity check: reject any disallowed character
  for (const ch of expr) {
    if (!allowedChars.has(ch)) return null;
  }

  try {
    const result = evaluate(expr);

    // Ensure the result is a finite number
    if (typeof result !== 'number' || !Number.isFinite(result)) return null;

    return result;
  } catch {
    return null;
  }
}
