response_prompt:
```js
const semver = require('semver');
const parseMetadata = require('npm-manifest-parser');

/**
 * Resolve a package manifest against a map of available versions.
 *
 * @param {string} packageMetaDataDocument - Raw package metadata (JSON string or object).
 * @param {Object.<string, string[]>} availableVersionsMap
 *   Map of dependency names to arrays of available version strings.
 * @returns {Object} Resolved manifest with concrete dependency versions.
 */
function resolveManifest(packageMetaDataDocument, availableVersionsMap) {
  const metadata = parseMetadata(packageMetaDataDocument);
  const dependencies = metadata.dependencies || {};

  const resolvedDependencies = {};

  for (const [depName, range] of Object.entries(dependencies)) {
    const available = availableVersionsMap[depName] || [];
    const resolved = semver.maxSatisfying(available, range, { loose: true });

    if (!resolved) {
      throw new Error(`No matching version for ${depName} ${range}`);
    }

    resolvedDependencies[depName] = resolved;
  }

  return {
    name: metadata.name,
    version: metadata.version,
    dependencies: resolvedDependencies
  };
}

module.exports = resolveManifest;
```

