```js
// svg-inline-loader.js
const path = require('path');
const fs = require('fs');
const { getSvgUrl } = require('svg-url');

module.exports = function (source) {
  const callback = this.async();
  const css = source.toString();
  const urlRegex = /url\(\s*(['"]?)([^'")]+\.svg)\1\s*\)/g;
  const replacements = {};
  const promises = [];

  let match;
  while ((match = urlRegex.exec(css)) !== null) {
    const url = match[2];
    if (!replacements[url]) {
      const absPath = path.resolve(this.rootContext, url);
      promises.push(
        new Promise((resolve, reject) => {
          fs.readFile(absPath, 'utf8', (err, data) => {
            if (err) return reject(err);
            replacements[url] = getSvgUrl(data);
            resolve();
          });
        })
      );
    }
  }

  Promise.all(promises)
    .then(() => {
      const result = css.replace(urlRegex, (_, q, u) => `url(${replacements[u]})`);
      callback(null, result);
    })
    .catch(err => callback(err));
};
```

