```javascript
import { StyleSheet } from 'react-native';
import csstox from 'csstox'; // npm install csstox

/**
 * Convert a CSS string into a React Native StyleSheet object.
 *
 * @param {string} cssText - The CSS source code.
 * @returns {object} React Native StyleSheet.
 */
export default function cssToRNStylesheet(cssText) {
  // Parse CSS into a plain JS object
  const parsed = csstox(cssText);

  // Convert selector keys to RN-friendly names
  const rnStyles = {};
  Object.entries(parsed).forEach(([selector, styles]) => {
    // Remove leading '.' or '#' from selector
    const key = selector.replace(/^[.#]/, '');
    rnStyles[key] = styles;
  });

  return StyleSheet.create(rnStyles);
}
