```js
// transformAsyncGenerators.js
const fs = require('fs');
const path = require('path');
const babel = require('@babel/core');
const parser = require('@babel/parser');
const traverse = require('@babel/traverse').default;
const generator = require('@babel/generator').default;
const { transformAsyncGenerator } = require('es2015-generator-utils');

/**
 * Transforms async generator functions in the given source code
 * into ES2015 generators using es2015-generator-utils.
 *
 * @param {string} src - The source code to transform.
 * @returns {string} The transformed code.
 */
function transformAsyncGenerators(src) {
  // Parse the source into an AST
  const ast = parser.parse(src, {
    sourceType: 'module',
    plugins: ['asyncGenerators', 'jsx', 'typescript'],
  });

  // Find async generator functions and transform them
  traverse(ast, {
    Function(path) {
      if (path.node.async && path.node.generator) {
        transformAsyncGenerator(path.node);
      }
    },
  });

  // Generate the transformed code
  const output = generator(ast, { /* options */ }, src);
  return output.code;
}

// Example usage: read a file, transform, and write back
if (require.main === module) {
  const inputPath = process.argv[2];
  if (!inputPath) {
    console.error('Usage: node transformAsyncGenerators.js <file>');
    process.exit(1);
  }
  const src = fs.readFileSync(inputPath, 'utf8');
  const transformed = transformAsyncGenerators(src);
  const outPath = path.join(
    path.dirname(inputPath),
    `${path.basename(inputPath, path.extname(inputPath))}.transformed${path.extname(inputPath)}`
  );
  fs.writeFileSync(outPath, transformed, 'utf8');
  console.log(`Transformed file written to ${outPath}`);
}

module.exports = transformAsyncGenerators;
```

