```js
// npm install pg pg-bytea-parser
const { Client } = require('pg');
const { parse } = require('pg-bytea-parser');

// Custom bytea parser (fallback if you don't want the library)
function customParseBytea(bytea) {
  // PostgreSQL bytea is returned as a string like '\\x48656c6c6f'
  if (!bytea.startsWith('\\x')) return bytea;
  const hex = bytea.slice(2);
  const buf = Buffer.from(hex, 'hex');
  // Try to interpret as UTF‑8 JSON, otherwise return raw string
  try {
    const json = JSON.parse(buf.toString('utf8'));
    return json;
  } catch {
    return buf.toString('utf8');
  }
}

async function main() {
  const client = new Client({
    connectionString: process.env.DATABASE_URL,
  });
  await client.connect();

  // Register pg-bytea-parser to automatically parse bytea columns
  client.on('row', (row) => {
    Object.entries(row).forEach(([key, value]) => {
      if (typeof value === 'string' && value.startsWith('\\x')) {
        // Use library parser
        row[key] = parse(value);
        // Or use custom parser:
        // row[key] = customParseBytea(value);
      }
    });
  });

  const res = await client.query(`
    SELECT id, data_bytea
    FROM my_table
    WHERE id = $1
  `, [1]);

  console.log(res.rows[0]); // data_bytea is now a JS object/string

  await client.end();
}

main().catch(console.error);
```

