 * and optionally converts it to a UTF‑8 string or JSON.
 *
 * @param {string} bytea - The bytea value returned by PostgreSQL.
 * @param {Object} [options] - Optional parsing options.
 * @param {boolean} [options.asString=false] - If true, return a UTF‑8 string.
 * @param {boolean} [options.asJson=false] - If true, parse the string as JSON.
 * @returns {Buffer|string|any} The parsed result.
 *
 * @throws {Error} If the input is not a valid bytea string.
 */
function parseBytea(bytea, options = {}) {
  const { asString = false, asJson = false } = options;

  if (typeof bytea !== 'string') {
    throw new Error('bytea must be a string');
  }

  // PostgreSQL hex format: starts with '\\x' followed by hex digits
  const hexMatch = bytea.match(/^\\x([0-9a-fA-F]+)$/);
  if (hexMatch) {
    const hex = hexMatch[1];
    if (hex.length % 2 !== 0) {
      throw new Error('Invalid hex bytea string');
    }
    const buf = Buffer.from(hex, 'hex');
    if (asString) return buf.toString('utf8');
    if (asJson) {
      try {
        return JSON.parse(buf.toString('utf8'));
      } catch (e) {
        throw new Error('Failed to parse JSON from bytea');
      }
    }
    return buf;
  }

  // PostgreSQL escape format: backslash-escaped octal or literal backslashes
  // Example: '\\001\\002\\003' or 'abc\\n'
  const escapeMatch = bytea.match(/^\\([0-7]{3})/);
  if (escapeMatch) {
    // Convert escape format to hex
    const escaped = bytea.replace(/\\([0-7]{3})/g, (m, oct) => {
      const byte = parseInt(oct, 8);
      return String.fromCharCode(byte);
    });
    const buf = Buffer.from(escaped, 'binary');
    if (asString) return buf.toString('utf8');
    if (asJson) {
      try {
        return JSON.parse(buf.toString('utf8'));
      } catch (e) {
        throw new Error('Failed to parse JSON from bytea');
      }
    }
    return buf;
  }

  // If it doesn't match known formats, treat it as raw binary string
  const buf = Buffer.from(bytea, 'binary');
  if (asString) return buf.toString('utf8');
  if (asJson) {
    try {
      return JSON.parse(buf.toString('utf8'));
    } catch (e) {
      throw new Error('Failed to parse JSON from bytea');
    }
  }
  return buf;
}

/* Example usage */

// Hex bytea containing a JSON string
const hexBytea = '\\x7b226e616d65223a202274657374227d'; // {"name": "test"}
console.log(parseBytea(hexBytea, { asJson: true })); // { name: 'test' }

// Escape bytea containing plain text
const escapeBytea = '\\001\\002Hello\\n';
console.log(parseBytea(escapeBytea, { asString: true })); // '\x01\x02Hello\n'

// Raw binary bytea
const rawBytea = 'binary data';
console.log(parseBytea(rawBytea)); // <Buffer 62 69 6e 61 72 79 20 64 61 74 61>
