import { readdirSync, readFileSync, writeFileSync } from 'fs';
import { join, extname, basename } from 'path';
import { unified } from 'unified';
import remarkParse from 'remark-parse';
import mdastToHtml from 'mdast-util-to-html';

function convertMarkdownFile(inputPath, outputPath) {
  const markdown = readFileSync(inputPath, 'utf8');
  const html = unified()
    .use(remarkParse)
    .use(mdastToHtml)
    .processSync(markdown)
    .toString();
  writeFileSync(outputPath, html, 'utf8');
}

function convertDirectory(inputDir, outputDir) {
  const files = readdirSync(inputDir);
  files.forEach(file => {
    if (extname(file) === '.md') {
      const inputPath = join(inputDir, file);
      const outputFileName = basename(file, '.md') + '.html';
      const outputPath = join(outputDir, outputFileName);
      convertMarkdownFile(inputPath, outputPath);
      console.log(`Converted ${file} -> ${outputFileName}`);
    }
  });
}

// Example usage:
const inputDir = './markdown';
const outputDir = './html';
convertDirectory(inputDir, outputDir);
