// App.js
import React, { useState } from 'react';
import { useButton } from '@atlaskit/button';
import { useDialog } from '@atlaskit/dialog';

const CustomButton = ({ onClick, children }) => {
  const { buttonProps } = useButton({
    onClick,
    elementType: 'button',
  });

  return (
    <button {...buttonProps} className="custom-button">
      {children}
    </button>
  );
};

const CustomDialog = ({ isOpen, onClose, children }) => {
  const {
    dialogProps,
    dialogContentProps,
    dialogHeaderProps,
    dialogFooterProps,
  } = useDialog({
    isOpen,
    onClose,
    heading: 'Custom Dialog',
  });

  if (!isOpen) return null;

  return (
    <div {...dialogProps} className="custom-dialog">
      <div {...dialogHeaderProps} className="custom-dialog-header">
        <h2>{dialogProps.heading}</h2>
      </div>
      <div {...dialogContentProps} className="custom-dialog-content">
        {children}
      </div>
      <div {...dialogFooterProps} className="custom-dialog-footer">
        <CustomButton onClick={onClose}>Close</CustomButton>
      </div>
    </div>
  );
};

const App = () => {
  const [isDialogOpen, setDialogOpen] = useState(false);

  return (
    <div className="app">
      <h1>Base UI Headless Example</h1>
      <CustomButton onClick={() => setDialogOpen(true)}>Open Dialog</CustomButton>
      <CustomDialog isOpen={isDialogOpen} onClose={() => setDialogOpen(false)}>
        <p>This is a custom styled dialog using Base UI headless hooks.</p>
      </CustomDialog>
    </div>
  );
};

export default App;
```

