```js
// parseSecureJSON.js
/**
 * Parses a JSON string safely, protecting against prototype pollution.
 * It uses JSON.parse and then recursively removes any __proto__, constructor,
 * or prototype keys from the resulting object.
 *
 * @param {string} jsonString - The JSON string to parse.
 * @returns {any} The parsed and sanitized JavaScript value.
 * @throws {SyntaxError} If the JSON is invalid.
 */
function parseSecureJSON(jsonString) {
  const parsed = JSON.parse(jsonString);

  function sanitize(obj) {
    if (obj && typeof obj === 'object') {
      if (Array.isArray(obj)) {
        return obj.map(sanitize);
      }
      const safeObj = {};
      for (const key of Object.keys(obj)) {
        if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
          continue; // skip dangerous keys
        }
        safeObj[key] = sanitize(obj[key]);
      }
      return safeObj;
    }
    return obj;
  }

  return sanitize(parsed);
}

// Example usage:
const jsonString = '{"name":"Alice","__proto__":{"admin":true}}';
try {
  const data = parseSecureJSON(jsonString);
  console.log(data); // { name: 'Alice' }
  console.log(JSON.stringify(data)); // {"name":"Alice"}
} catch (e) {
  console.error('Invalid JSON:', e);
}
