// micromark-parser.js
import micromark from 'micromark';
import gfm from 'micromark-extension-gfm';
import footnote from 'micromark-extension-footnote';
import mdx from 'micromark-extension-mdx';
import { createTokenizer } from 'micromark-core';
import { syntaxTree } from 'micromark-util-syntax-tree';

/**
 * Parses Markdown into a syntax tree (parse tree).
 *
 * @param {string} markdown - The Markdown source to parse.
 * @param {object} [options] - Optional micromark options.
 * @returns {object} The syntax tree root node.
 * @throws {Error} If parsing fails.
 */
export function parseMarkdown(markdown, options = {}) {
  // Merge user options with defaults that enable common edge cases.
  const defaultOptions = {
    extensions: [gfm(), footnote(), mdx()],
    // Enable parsing of tables, footnotes, and MDX syntax.
    // The `sourcePosition` option adds line/column info to nodes.
    sourcePosition: true,
  };

  const finalOptions = { ...defaultOptions, ...options };

  try {
    // Parse the markdown into a syntax tree.
    const tree = syntaxTree(micromark(markdown, finalOptions));
    return tree;
  } catch (err) {
    // Re‑throw with a clearer message.
    throw new Error(`Markdown parsing failed: ${err.message}`);
  }
}
