```js
// npm install sass-parse
const fs = require('fs');
const path = require('path');
const sassParse = require('sass-parse');

/**
 * Simple directed graph representation.
 * Nodes are file paths, edges are imports.
 */
class ImportGraph {
  constructor() {
    this.adj = new Map(); // file -> Set of imported files
  }

  addNode(file) {
    if (!this.adj.has(file)) this.adj.set(file, new Set());
  }

  addEdge(from, to) {
    this.addNode(from);
    this.addNode(to);
    this.adj.get(from).add(to);
  }

  getAdjacencyList() {
    const obj = {};
    for (const [k, v] of this.adj.entries()) obj[k] = Array.from(v);
    return obj;
  }
}

/**
 * Recursively parse a Sass file and its imports.
 * @param {string} filePath - Absolute path to the Sass file.
 * @param {ImportGraph} graph - Graph to populate.
 * @param {Set<string>} visited - Set of already processed files.
 */
function parseFile(filePath, graph, visited) {
  const absPath = path.resolve(filePath);
  if (visited.has(absPath)) return;
  visited.add(absPath);

  const content = fs.readFileSync(absPath, 'utf8');
  const ast = sassParse(content);

  // Find all import nodes
  const imports = [];
  function walk(node) {
    if (!node) return;
    if (node.type === 'Import') imports.push(node);
    if (node.children) node.children.forEach(walk);
  }
  walk(ast);

  imports.forEach((imp) => {
    // imp.value is an array of import paths (strings)
    imp.value.forEach((importPath) => {
      // Resolve relative imports
      const resolved = path.resolve(path.dirname(absPath), importPath);
      graph.addEdge(absPath, resolved);
      parseFile(resolved, graph, visited);
    });
  });
}

/**
 * Build an import graph starting from an entry Sass file.
 * @param {string} entryFile - Path to the entry Sass file.
 * @returns {ImportGraph}
 */
function buildImportGraph(entryFile) {
  const graph = new ImportGraph();
  parseFile(entryFile, graph, new Set());
  return graph;
}

// Example usage:
// const graph = buildImportGraph('./src/styles/main.scss');
// console.log(JSON.stringify(graph.getAdjacencyList(), null, 2));
