```javascript
// unicodeTrie.js

// 1. Import required modules
const icu = require('icu-js');          // ICU bindings for Unicode data
const Trie = require('javascript-trie'); // Generic trie implementation

/**
 * Node structure for the Unicode Trie.
 * Each node represents a range of code points.
 */
class UnicodeTrieNode {
  constructor(start, end) {
    this.start = start;          // Inclusive start of the range
    this.end = end;              // Inclusive end of the range
    this.children = [];          // Child nodes (sub‑ranges)
    this.metadata = {};          // Metadata for the range (if any)
  }

  /**
   * Find or create a child node that covers the given code point.
   * @param {number} cp - Code point to insert.
   * @returns {UnicodeTrieNode} - The child node covering cp.
   */
  getOrCreateChild(cp) {
    // Search for an existing child that covers cp
    for (const child of this.children) {
      if (cp >= child.start && cp <= child.end) {
        return child;
      }
    }
    // If not found, create a new child that covers only cp
    const newChild = new UnicodeTrieNode(cp, cp);
    this.children.push(newChild);
    return newChild;
  }

  /**
   * Recursively search for the node that contains the code point.
   * @param {number} cp - Code point to look up.
   * @returns {UnicodeTrieNode|null}
   */
  findNode(cp) {
    if (cp < this.start || cp > this.end) return null;
    for (const child of this.children) {
      const res = child.findNode(cp);
      if (res) return res;
    }
    return this; // If no child matches, this node is the match
  }
}

/**
 * Builds a Unicode Trie from a string of characters.
 * @param {string} str - Input string containing Unicode characters.
 * @returns {UnicodeTrieNode} - Root of the constructed trie.
 */
function buildUnicodeTrie(str) {
  const root = new UnicodeTrieNode(0, 0x10FFFF); // Full Unicode range

  for (const ch of str) {
    const cp = ch.codePointAt(0);
    const node = root.getOrCreateChild(cp);

    // Retrieve metadata from ICU
    const data = icu.getUnicodeData(ch); // { codePoint, name, category, ... }

    // Store metadata at the leaf node
    node.metadata = {
      codePoint: data.codePoint,
      name: data.name,
      category: data.category,
    };
  }

  return root;
}

/**
 * Unicode Trie wrapper providing lookup methods.
 */
class UnicodeTrie {
  constructor(root) {
    this.root = root;
  }

  /**
   * Lookup metadata for a single character.
   * @param {string} ch - Character to look up.
   * @returns {object|null} - Metadata object or null if not found.
   */
  lookup(ch) {
    const cp = ch.codePointAt(0);
    const node = this.root.findNode(cp);
    return node ? node.metadata : null;
  }

  /**
   * Get the code point of a character.
   * @param {string} ch
   * @returns {number|null}
   */
  getCodePoint(ch) {
    const meta = this.lookup(ch);
    return meta ? meta.codePoint : null;
  }

  /**
   * Get the Unicode name of a character.
   * @param {string} ch
   * @returns {string|null}
   */
  getName(ch) {
    const meta = this.lookup(ch);
    return meta ? meta.name : null;
  }

  /**
   * Get the Unicode category of a character.
   * @param {string} ch
   * @returns {string|null}
   */
  getCategory(ch) {
    const meta = this.lookup(ch);
    return meta ? meta.category : null;
  }
}

// 5. Export the module
module.exports = {
  buildUnicodeTrie,
  UnicodeTrie,
};
```

