// eventstream-serde.js
const { createSerde } = require('eventstream-serde-node');

/**
 * Serializer / Deserializer for EventStream events.
 *
 * The `serialize` function turns an event object into a string
 * that can be written to the stream.  The `deserialize` function
 * parses a string read from the stream back into an event object.
 */
const eventStreamSerde = createSerde({
  serialize: (event) => {
    // Convert the event object to a JSON string.
    // Adjust this if your events need a different format.
    return JSON.stringify(event);
  },

  deserialize: (data) => {
    // Parse the JSON string back into an event object.
    // Add error handling if needed.
    return JSON.parse(data);
  },
});

module.exports = eventStreamSerde;
