/**
 * Encode an SVG string into a compact data URI.
 * @param {string} svg - The raw SVG markup.
 * @returns {string} Data URI suitable for CSS, HTML, etc.
 */
export function encodeSvg(svg) {
  // Use svg-url-encode for a compact, URL‑safe representation
  return `data:image/svg+xml,${svgUrlEncode(svg)}`;
}

/**
 * Encode an SVG string into a base64 data URI (fallback for older browsers).
 * @param {string} svg - The raw SVG markup.
 * @returns {string} Base64 data URI.
 */
export function encodeSvgBase64(svg) {
  // btoa is available in browsers; for Node use Buffer
  const base64 = typeof btoa === 'function'
    ? btoa(svg)
    : Buffer.from(svg, 'utf-8').toString('base64');
  return `data:image/svg+xml;base64,${base64}`;
}

/**
 * Get a data URI for an SVG, optionally using base64.
 * @param {string} svg - The raw SVG markup.
 * @param {Object} [options] - Options.
 * @param {boolean} [options.base64=false] - Whether to use base64 encoding.
 * @returns {string} Data URI.
 */
export function getSvgDataUri(svg, options = {}) {
  return options.base64 ? encodeSvgBase64(svg) : encodeSvg(svg);
}

/* Example usage:
import { getSvgDataUri } from './svgDataUri.js';

const svgMarkup = `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100">
  <circle cx="50" cy="50" r="40" fill="red"/>
</svg>`;

const dataUri = getSvgDataUri(svgMarkup); // compact URL‑encoded
// or
const dataUriBase64 = getSvgDataUri(svgMarkup, { base64: true });

document.body.style.backgroundImage = `url("${dataUri}")`;
*/
```

