```js
// Import the conversion helper from the sql-br-bridge library
import { convertNamedToUnnamed } from 'sql-br-bridge';

/**
 * Executes a SQL query that uses named placeholders.
 *
 * @param {string} sqlNamed   The SQL string with named placeholders (e.g. ":name").
 * @param {Object} params     An object mapping placeholder names to values.
 * @returns {Promise<Object>} The result of the query.
 */
async function executeNamedQuery(sqlNamed, params) {
  // Convert named placeholders to unnamed "?" placeholders
  const { sql, values } = convertNamedToUnnamed(sqlNamed, params);

  // Example: using the pg library to run the query
  // (Replace with your preferred DB client)
  const { Client } = await import('pg');
  const client = new Client({ connectionString: process.env.DATABASE_URL });
  await client.connect();

  try {
    const res = await client.query(sql, values);
    return res;
  } finally {
    await client.end();
  }
}

// Example usage
const sqlNamed = `
  SELECT id, name, email
  FROM users
  WHERE status = :status
    AND created_at >= :startDate
    AND created_at <= :endDate
`;
const params = {
  status: 'active',
  startDate: '2023-01-01',
  endDate: '2023-12-31',
};

executeNamedQuery(sqlNamed, params)
  .then(result => console.log('Rows:', result.rows))
  .catch(err => console.error('Query error:', err));
