// Install the required packages first:
//   npm install unified remark-parse remark-stringify remark-gfm-footnotes

const unified = require('unified')
const remarkParse = require('remark-parse')
const remarkStringify = require('remark-stringify')
const remarkGfmFootnotes = require('remark-gfm-footnotes')

// Sample Markdown that contains GFM footnotes
const markdown = `
Here is a sentence with a footnote.[^1]

[^1]: This is the footnote content.
`

// Create a processor that can parse and serialize GFM footnotes
const processor = unified()
  .use(remarkParse)          // Parse Markdown to MDAST
  .use(remarkGfmFootnotes)   // Enable GFM footnote support
  .use(remarkStringify)      // Serialize MDAST back to Markdown

// Parse the Markdown into an AST
const ast = processor.parse(markdown)
console.log('AST:', JSON.stringify(ast, null, 2))

// Serialize the AST back to Markdown
const serialized = processor.stringify(ast)
console.log('\nSerialized Markdown:\n', serialized)
```

This script:

1. **Parses** a Markdown string containing GFM footnotes into an MDAST.
2. **Serializes** the same AST back into Markdown, preserving the footnote syntax.
3. Uses the `remark-gfm-footnotes` extension to handle footnote parsing and stringification.

```js
// Import the Awesome Media Queries library (ES module)
import { media } from 'awesome-media-queries';

// Define common breakpoints and device characteristics
const mq = {
  // Screen width breakpoints
  xs: media({ maxWidth: 575 }),
  sm: media({ minWidth: 576, maxWidth: 767 }),
  md: media({ minWidth: 768, maxWidth: 991 }),
  lg: media({ minWidth: 992, maxWidth: 1199 }),
  xl: media({ minWidth: 1200 }),

  // Orientation
  portrait: media({ orientation: 'portrait' }),
  landscape: media({ orientation: 'landscape' }),

  // Touch capability
  touch: media({ hover: 'none' }),

  // High‑density displays
  retina: media({ resolution: '2dppx' })
};

// Helper to update CSS variables or classes based on active queries
function updateResponsiveStyles() {
  // Grid columns based on width
  if (mq.xs.matches) {
    document.documentElement.style.setProperty('--grid-columns', '1');
  } else if (mq.sm.matches) {
    document.documentElement.style.setProperty('--grid-columns', '2');
  } else if (mq.md.matches) {
    document.documentElement.style.setProperty('--grid-columns', '3');
  } else if (mq.lg.matches) {
    document.documentElement.style.setProperty('--grid-columns', '4');
  } else if (mq.xl.matches) {
    document.documentElement.style.setProperty('--grid-columns', '5');
  }

  // Orientation classes
  if (mq.portrait.matches) {
    document.body.classList.add('portrait');
    document.body.classList.remove('landscape');
  } else if (mq.landscape.matches) {
    document.body.classList.add('landscape');
    document.body.classList.remove('portrait');
  }

  // Touch support
  if (mq.touch.matches) {
    document.body.classList.add('touch');
  } else {
    document.body.classList.remove('touch');
  }

  // Retina display
  if (mq.retina.matches) {
    document.documentElement.style.setProperty('--image-resolution', '2x');
  } else {
    document.documentElement.style.setProperty('--image-resolution', '1x');
  }
}

// Attach listeners to all queries
Object.values(mq).forEach(q => q.addListener(updateResponsiveStyles));

// Initial run
updateResponsiveStyles();
