```js
// notifyClient.js
// A lightweight wrapper around the GOV.UK Notify Node.js client
// Usage:
//   const NotifyClient = require('./notifyClient');
//   const client = new NotifyClient(process.env.NOTIFY_API_KEY);
//   await client.sendEmail('template-id', 'user@example.com', { name: 'John' });
//   await client.sendSms('template-id', '+447700900123', { name: 'John' });

const { NotifyClient: Notify } = require('notify-client');

class NotifyClient {
  /**
   * @param {string} apiKey - GOV.UK Notify API key
   */
  constructor(apiKey) {
    if (!apiKey) {
      throw new Error('Notify API key is required');
    }
    this.client = new Notify(apiKey);
  }

  /**
   * Send an email notification
   * @param {string} templateId - The Notify template ID
   * @param {string} email - Recipient email address
   * @param {object} personalisation - Personalisation variables
   * @param {object} [options] - Optional parameters (e.g., reference, replyTo)
   * @returns {Promise<object>} - Response from Notify
   */
  async sendEmail(templateId, email, personalisation = {}, options = {}) {
    try {
      const payload = {
        template_id: templateId,
        email_address: email,
        personalisation,
        ...options,
      };
      return await this.client.sendEmail(payload);
    } catch (err) {
      this._handleError(err);
    }
  }

  /**
   * Send an SMS notification
   * @param {string} templateId - The Notify template ID
   * @param {string} phoneNumber - Recipient phone number (E.164 format)
   * @param {object} personalisation - Personalisation variables
   * @param {object} [options] - Optional parameters (e.g., reference)
   * @returns {Promise<object>} - Response from Notify
   */
  async sendSms(templateId, phoneNumber, personalisation = {}, options = {}) {
    try {
      const payload = {
        template_id: templateId,
        phone_number: phoneNumber,
        personalisation,
        ...options,
      };
      return await this.client.sendSms(payload);
    } catch (err) {
      this._handleError(err);
    }
  }

  /**
   * Send a letter notification
   * @param {string} templateId - The Notify template ID
   * @param {object} personalisation - Personalisation variables
   * @param {object} [options] - Optional parameters (e.g., reference, postage)
   * @returns {Promise<object>} - Response from Notify
   */
  async sendLetter(templateId, personalisation = {}, options = {}) {
    try {
      const payload = {
        template_id: templateId,
        personalisation,
        ...options,
      };
      return await this.client.sendLetter(payload);
    } catch (err) {
      this._handleError(err);
    }
  }

  /**
   * Internal error handler
   * @param {Error} err
   */
  _handleError(err) {
    if (err.response && err.response.body) {
      const { errors } = err.response.body;
      const message = errors && errors.length
        ? errors.map(e => e.message).join('; ')
        : err.message;
      throw new Error(`Notify error: ${message}`);
    }
    throw err;
  }
}

module.exports = NotifyClient;
```

```js
// measure-webpack.js
// Run: node measure-webpack.js
// Requires: webpack, webpack-perf, fs, path

const path = require('path');
const fs = require('fs');
const webpack = require('webpack');
const WebpackPerfPlugin = require('webpack-perf');

// 1. Create a minimal webpack config that uses webpack-perf
const config = {
  mode: 'production',
  entry: './src/index.js',          // adjust to your entry point
  output: {
    path: path.resolve(__dirname, 'dist'),
    filename: 'bundle.js',
  },
  module: {
    rules: [
      // Example loader
      {
        test: /\.js$/,
        use: [
          {
            loader: 'babel-loader',
            options: { presets: ['@babel/preset-env'] },
          },
        ],
      },
    ],
  },
  plugins: [
    // webpack-perf plugin writes performance data to a JSON file
    new WebpackPerfPlugin({
      // Optional: customize output file name
      outputFile: 'webpack-perf.json',
      // Optional: include loader and plugin timings
      includeLoaders: true,
      includePlugins: true,
    }),
  ],
};

// 2. Run webpack programmatically
webpack(config, (err, stats) => {
  if (err) {
    console.error('Webpack build failed:', err);
    return;
  }
  if (stats.hasErrors()) {
    console.error('Webpack build errors:', stats.toJson().errors);
    return;
  }

  console.log('Webpack build completed.');

  // 3. Read the performance data generated by webpack-perf
  const perfFile = path.resolve(__dirname, 'webpack-perf.json');
  if (!fs.existsSync(perfFile)) {
    console.error('Performance file not found:', perfFile);
    return;
  }

  const perfData = JSON.parse(fs.readFileSync(perfFile, 'utf8'));

  // 4. Compute and display statistics
  console.log('\n=== Webpack Performance Summary ===');

  // Total build time
  const totalTime = perfData.totalTime || 0;
  console.log(`Total build time: ${totalTime.toFixed(2)} ms`);

  // Overhead (time spent in loaders/plugins)
  const overhead = perfData.overhead || 0;
  console.log(`Overhead (loaders + plugins): ${overhead.toFixed(2)} ms`);

  // Size gaps (difference between input and output sizes)
  const sizeGap = (perfData.inputSize || 0) - (perfData.outputSize || 0);
  console.log(`Size gap: ${sizeGap} bytes`);

  // Loader statistics
  if (perfData.loaders && Object.keys(perfData.loaders).length) {
    console.log('\n--- Loader Stats ---');
    Object.entries(perfData.loaders).forEach(([loaderName, loaderInfo]) => {
      const time = loaderInfo.time || 0;
      const overheadPerc = ((time / totalTime) * 100).toFixed(2);
      console.log(
        `${loaderName}: ${time.toFixed(2)} ms (${overheadPerc}% of total)`
      );
    });
  }

  // Plugin statistics
  if (perfData.plugins && Object.keys(perfData.plugins).length) {
    console.log('\n--- Plugin Stats ---');
    Object.entries(perfData.plugins).forEach(([pluginName, pluginInfo]) => {
      const time = pluginInfo.time || 0;
      const overheadPerc = ((time / totalTime) * 100).toFixed(2);
      console.log(
        `${pluginName}: ${time.toFixed(2)} ms (${overheadPerc}% of total)`
      );
    });
  }

  // Clean up: remove the perf file if you don't need it
  // fs.unlinkSync(perfFile);
});
