```js
// Dependencies: npm install swagger2openapi ajv ajv-formats ajv-openapi-schema
const fs = require('fs').promises;
const swagger2openapi = require('swagger2openapi');
const Ajv = require('ajv');
const addFormats = require('ajv-formats');
const openapiSchema = require('ajv-openapi-schema');

async function convertAndValidate(swaggerPath, outputPath) {
  const swaggerContent = await fs.readFile(swaggerPath, 'utf8');
  const swaggerDoc = JSON.parse(swaggerContent);

  const { openapi, ...rest } = await swagger2openapi.convertObj(swaggerDoc, { patch: true });

  const openapiDoc = { openapi: '3.0.0', ...rest };

  const ajv = new Ajv({ allErrors: true, strict: false });
  addFormats(ajv);
  const validate = ajv.compile(openapiSchema);
  if (!validate(openapiDoc)) {
    console.error('OpenAPI validation errors:', validate.errors);
    throw new Error('OpenAPI document is invalid');
  }

  await fs.writeFile(outputPath, JSON.stringify(openapiDoc, null, 2));
  console.log(`Converted and validated OpenAPI 3.0 document written to ${outputPath}`);
}

module.exports = { convertAndValidate };
```

```js
const fs = require('fs');
const sass = require('sass-js'); // npm install sass-js

/**
 * Recursively walk the Sass AST and collect import paths.
 * @param {Object} node - AST node
 * @param {Array<string>} deps - accumulator for dependencies
 */
function walk(node, deps) {
  if (!node) return;

  // Import nodes in sass-js AST are of type 'Import'
  if (node.type === 'Import' && node.value) {
    // node.value may contain the import path string
    deps.push(node.value);
  }

  // Recurse into child nodes if they exist
  if (node.children && Array.isArray(node.children)) {
    node.children.forEach(child => walk(child, deps));
  }
}

/**
 * Get a list of Sass dependencies (imported files) from a .scss/.sass file.
 * @param {string} filePath - Path to the Sass file
 * @returns {Promise<string[]>} - Array of dependency paths
 */
async function getSassDependencies(filePath) {
  const content = await fs.promises.readFile(filePath, 'utf8');

  // Parse the Sass file into an AST
  const ast = sass.parse(content);

  const deps = [];
  walk(ast, deps);

  return deps;
}

// Example usage:
(async () => {
  const deps = await getSassDependencies('./styles/main.scss');
  console.log('Dependencies:', deps);
})();
