```js
import { GraphQLScalarType, Kind } from 'graphql';
import { v4 as uuidv4, validate as uuidValidate } from 'uuid';
import { isIP } from 'net';
import { parsePhoneNumberFromString } from 'libphonenumber-js';

// IP Address scalar
export const IPAddress = new GraphQLScalarType({
  name: 'IPAddress',
  description: 'An IPv4 or IPv6 address',
  serialize(value) {
    if (typeof value !== 'string' || !isIP(value)) {
      throw new TypeError(`Value is not a valid IP address: ${value}`);
    }
    return value;
  },
  parseValue(value) {
    if (typeof value !== 'string' || !isIP(value)) {
      throw new TypeError(`Value is not a valid IP address: ${value}`);
    }
    return value;
  },
  parseLiteral(ast) {
    if (ast.kind !== Kind.STRING || !isIP(ast.value)) {
      throw new TypeError(`Value is not a valid IP address: ${ast.value}`);
    }
    return ast.value;
  },
});

// UUID scalar
export const UUID = new GraphQLScalarType({
  name: 'UUID',
  description: 'A UUID (v4) string',
  serialize(value) {
    if (typeof value !== 'string' || !uuidValidate(value)) {
      throw new TypeError(`Value is not a valid UUID: ${value}`);
    }
    return value;
  },
  parseValue(value) {
    if (typeof value !== 'string' || !uuidValidate(value)) {
      throw new TypeError(`Value is not a valid UUID: ${value}`);
    }
    return value;
  },
  parseLiteral(ast) {
    if (ast.kind !== Kind.STRING || !uuidValidate(ast.value)) {
      throw new TypeError(`Value is not a valid UUID: ${ast.value}`);
    }
    return ast.value;
  },
});

// Telephone Number scalar
export const PhoneNumber = new GraphQLScalarType({
  name: 'PhoneNumber',
  description: 'A phone number in E.164 format',
  serialize(value) {
    const phone = parsePhoneNumberFromString(value);
    if (!phone || !phone.isValid()) {
      throw new TypeError(`Value is not a valid phone number: ${value}`);
    }
    return phone.number; // E.164 format
  },
  parseValue(value) {
    const phone = parsePhoneNumberFromString(value);
    if (!phone || !phone.isValid()) {
      throw new TypeError(`Value is not a valid phone number: ${value}`);
    }
    return phone.number;
  },
  parseLiteral(ast) {
    if (ast.kind !== Kind.STRING) {
      throw new TypeError(`Value is not a valid phone number: ${ast.value}`);
    }
    const phone = parsePhoneNumberFromString(ast.value);
    if (!phone || !phone.isValid()) {
      throw new TypeError(`Value is not a valid phone number: ${ast.value}`);
    }
    return phone.number;
  },
});

// Geographic Coordinates scalar
export const GeoCoordinate = new GraphQLScalarType({
  name: 'GeoCoordinate',
  description: 'Geographic coordinates as an object { latitude: Float, longitude: Float }',
  serialize(value) {
    if (
      typeof value !== 'object' ||
      typeof value.latitude !== 'number' ||
      typeof value.longitude !== 'number' ||
      value.latitude < -90 ||
      value.latitude > 90 ||
      value.longitude < -180 ||
      value.longitude > 180
    ) {
      throw new TypeError(`Value is not a valid GeoCoordinate: ${JSON.stringify(value)}`);
    }
    return value;
  },
  parseValue(value) {
    if (
      typeof value !== 'object' ||
      typeof value.latitude !== 'number' ||
      typeof value.longitude !== 'number' ||
      value.latitude < -90 ||
      value.latitude > 90 ||
      value.longitude < -180 ||
      value.longitude > 180
    ) {
      throw new TypeError(`Value is not a valid GeoCoordinate: ${JSON.stringify(value)}`);
    }
    return value;
  },
  parseLiteral(ast) {
    if (ast.kind !== Kind.OBJECT) {
      throw new TypeError(`Value is not a valid GeoCoordinate: ${JSON.stringify(ast)}`);
    }
    const fields = ast.fields.reduce((acc, field) => {
      acc[field.name.value] = field.value;
      return acc;
    }, {});
    const latitude = fields.latitude?.value;
    const longitude = fields.longitude?.value;
    if (
      typeof latitude !== 'number' ||
      typeof longitude !== 'number' ||
      latitude < -90 ||
      latitude > 90 ||
      longitude < -180 ||
      longitude > 180
    ) {
      throw new TypeError(`Value is not a valid GeoCoordinate: ${JSON.stringify(fields)}`);
    }
    return { latitude, longitude };
  },
});
