```javascript
// PhoneInput.js
import React, { useState, useEffect } from 'react';
import { parsePhoneNumberFromString, isPossiblePhoneNumber } from 'libphonenumber-js';
import CountryFlag from 'react-country-flag';

// Minimal list of countries (ISO 3166-1 alpha-2) with their calling codes
const COUNTRY_LIST = [
  { code: 'US', name: 'United States', dialCode: '+1' },
  { code: 'GB', name: 'United Kingdom', dialCode: '+44' },
  { code: 'CA', name: 'Canada', dialCode: '+1' },
  { code: 'AU', name: 'Australia', dialCode: '+61' },
  { code: 'DE', name: 'Germany', dialCode: '+49' },
  // Add more countries as needed
];

export default function PhoneInput({ onChange }) {
  const [selectedCountry, setSelectedCountry] = useState(COUNTRY_LIST[0]);
  const [phoneNumber, setPhoneNumber] = useState('');
  const [isValid, setIsValid] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    const fullNumber = `${selectedCountry.dialCode}${phoneNumber}`;
    const parsed = parsePhoneNumberFromString(fullNumber);
    if (parsed && parsed.isValid()) {
      setIsValid(true);
      setError('');
      onChange && onChange(parsed.number);
    } else {
      setIsValid(false);
      setError('Invalid phone number');
      onChange && onChange(null);
    }
  }, [phoneNumber, selectedCountry, onChange]);

  const handleCountryChange = (e) => {
    const country = COUNTRY_LIST.find(c => c.code === e.target.value);
    setSelectedCountry(country);
  };

  const handleNumberChange = (e) => {
    const value = e.target.value.replace(/\D/g, ''); // keep digits only
    setPhoneNumber(value);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', maxWidth: 300 }}>
      <label>
        Country
        <select value={selectedCountry.code} onChange={handleCountryChange}>
          {COUNTRY_LIST.map(c => (
            <option key={c.code} value={c.code}>
              {c.name} ({c.dialCode})
            </option>
          ))}
        </select>
      </label>

      <label style={{ marginTop: 8 }}>
        Phone Number
        <div style={{ display: 'flex', alignItems: 'center' }}>
          <CountryFlag countryCode={selectedCountry.code} svg style={{ marginRight: 8 }} />
          <input
            type="tel"
            value={phoneNumber}
            onChange={handleNumberChange}
            placeholder="Enter number"
            style={{ flex: 1 }}
          />
        </div>
      </label>

      {!isValid && error && (
        <span style={{ color: 'red', marginTop: 4 }}>{error}</span>
      )}
    </div>
  );
}
```

```javascript
// index.js
// Node.js script to scan codebase for quality, security, performance, maintainability,
// and post findings to JIRA and GitHub.

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');
const axios = require('axios');
const { Octokit } = require("@octokit/rest");

// ---------- Config ----------
const JIRA_BASE_URL = 'https://your-domain.atlassian.net';
const JIRA_USER = 'email@example.com';
const JIRA_API_TOKEN = 'YOUR_JIRA_API_TOKEN';
const JIRA_PROJECT_KEY = 'PROJ';

const GITHUB_TOKEN = 'YOUR_GITHUB_TOKEN';
const GITHUB_OWNER = 'your-org';
const GITHUB_REPO = 'your-repo';
const GITHUB_PR_NUMBER = 123; // or fetch dynamically

// ---------- Helper ----------
async function runCommand(cmd, cwd = process.cwd()) {
  try {
    return execSync(cmd, { cwd, encoding: 'utf8' });
  } catch (e) {
    return e.stdout || e.message;
  }
}

// ---------- Scanners ----------
async function runESLint() {
  const output = await runCommand('npx eslint . --format json');
  return JSON.parse(output);
}

async function runNpmAudit() {
  const output = await runCommand('npm audit --json');
  return JSON.parse(output);
}

async function runLighthouse() {
  // Requires lighthouse CLI installed globally
  const output = await runCommand('lighthouse http://localhost:3000 --output json --quiet');
  return JSON.parse(output);
}

function analyzeMaintainability() {
  // Simple maintainability index using 'maintainability-index' npm package
  const mi = require('maintainability-index');
  const src = fs.readFileSync('src/index.js', 'utf8');
  const result = mi.calculate(src);
  return { maintainabilityIndex: result.index };
}

// ---------- Reporting ----------
async function postToJira(summary, description) {
  const auth = Buffer.from(`${JIRA_USER}:${JIRA_API_TOKEN}`).toString('base64');
  const url = `${JIRA_BASE_URL}/rest/api/3/issue`;
  const payload = {
    fields: {
      project: { key: JIRA_PROJECT_KEY },
      summary,
      description,
      issuetype: { name: 'Task' },
    },
  };
  await axios.post(url, payload, {
    headers: { Authorization: `Basic ${auth}`, 'Content-Type': 'application/json' },
  });
}

async function postToGitHubComment(body) {
  const octokit = new Octokit({ auth: GITHUB_TOKEN });
  await octokit.issues.createComment({
    owner: GITHUB_OWNER,
    repo: GITHUB_REPO,
    issue_number: GITHUB_PR_NUMBER,
    body,
  });
}

// ---------- Main ----------
(async () => {
  const eslintResults = await runESLint();
  const auditResults = await runNpmAudit();
  const lighthouseResults = await runLighthouse();
  const maintainability = analyzeMaintainability();

  const report = {
    eslint: eslintResults,
    audit: auditResults,
    lighthouse: lighthouseResults,
    maintainability,
  };

  const summary = `Code Quality Scan Report - ${new Date().toISOString()}`;
  const description = `\`\`\`json\n${JSON.stringify(report, null, 2)}\n\`\`\``;

  // Post to JIRA
  await postToJira(summary, description);

  // Post to GitHub PR comment
  await postToGitHubComment(`### Code Quality Scan Report\n${description}`);

  console.log('Scan complete and reports posted.');
})();
```

```javascript
// index.js
import React, { useRef, useEffect } from 'react';
import { Animated, Easing, View, StyleSheet } from 'react-native';

/**
 * Hook that returns an animated value and a start function.
 * @param {number} initialValue - The starting value of the animation.
 * @param {object} config - Animation configuration: { toValue, duration, easing, useNativeDriver }.
 */
export const useAnimation = (initialValue = 0, config = {}) => {
  const animatedValue = useRef(new Animated.Value(initialValue)).current;

  const start = () => {
    Animated.timing(animatedValue, {
      toValue: config.toValue ?? 1,
      duration: config.duration ?? 300,
      easing: config.easing ?? Easing.inOut(Easing.ease),
      useNativeDriver: config.useNativeDriver ?? false,
    }).start();
  };

  return { animatedValue, start };
};

/**
 * Declarative transition component.
 * @param {object} props
 * @param {React.ReactNode} props.children
 * @param {number} props.duration
 * @param {function} props.onTransitionEnd
 * @param {string} props.transition - 'fade', 'slide', 'scale'
 * @param {object} props.style
 */
export const Transition = ({
  children,
  duration = 300,
  onTransitionEnd,
  transition = 'fade',
  style,
}) => {
  const animatedValue = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    Animated.timing(animatedValue, {
      toValue: 1,
      duration,
      easing: Easing.inOut(Easing.ease),
      useNativeDriver: true,
    }).start(onTransitionEnd);
  }, [duration, onTransitionEnd]);

  const animatedStyle = (() => {
    switch (transition) {
      case 'slide':
        return {
          transform: [
            {
              translateY: animatedValue.interpolate({
                inputRange: [0, 1],
                outputRange: [50, 0],
              }),
            },
          ],
          opacity: animatedValue,
        };
      case 'scale':
        return {
          transform: [
            {
              scale: animatedValue.interpolate({
                inputRange: [0, 1],
                outputRange: [0.8, 1],
              }),
            },
          ],
          opacity: animatedValue,
        };
      case 'fade':
      default:
        return { opacity: animatedValue };
    }
  })();

  return (
    <Animated.View style={[style, animatedStyle]}>
      {children}
    </Animated.View>
  );
};

/**
 * Simple wrapper around Animated.View that accepts declarative props.
 * @param {object} props
 * @param {number} props.opacity
 * @param {number} props.scale
 * @param {number} props.translateX
 * @param {number} props.translateY
 * @param {object} props.style
 * @param {React.ReactNode} props.children
 */
export const AnimatedView = ({
  opacity,
  scale,
  translateX,
  translateY,
  style,
  children,
  ...rest
}) => {
  const animatedStyle = {
    opacity,
    transform: [
      { translateX },
      { translateY },
      { scale },
    ].filter(Boolean),
  };

  return (
    <Animated.View style={[style, animatedStyle]} {...rest}>
      {children}
    </Animated.View>
  );
};

/**
 * Example usage:
 *
 * import { Transition, useAnimation, AnimatedView } from 'your-library';
 *
 * const MyComponent = () => {
 *   const { animatedValue, start } = useAnimation(0, { toValue: 1, duration: 500 });
 *
 *   return (
 *     <Transition transition="slide" duration={400}>
 *       <AnimatedView opacity={animatedValue} style={styles.box} />
 *     </Transition>
 *   );
 * };
 *
 * const styles = StyleSheet.create({
 *   box: { width: 100, height: 100, backgroundColor: 'tomato' },
 * });
 */
