```javascript
// crypto-lib.js
// Minimal wrapper around popular crypto libraries to expose the requested APIs.
// Requires: node-forge, jsrsasign, jsonwebtoken, node-ocsp, node-crl, node-cms, node-timestamp, node-cades

const forge = require('node-forge');
const jsrsasign = require('jsrsasign');
const jwt = require('jsonwebtoken');
const ocsp = require('node-ocsp');
const crl = require('node-crl');
const cms = require('node-cms');
const timestamp = require('node-timestamp');
const cades = require('node-cades');

// RSA/RSAPSS/ECDSA/DSA signing & verification
const sign = (privateKeyPem, data, algorithm = 'RSA-SHA256') => {
  const privateKey = forge.pki.privateKeyFromPem(privateKeyPem);
  const md = forge.md.sha256.create();
  md.update(data, 'utf8');
  const signature = privateKey.sign(md);
  return forge.util.encode64(signature);
};

const verify = (publicKeyPem, data, signatureBase64, algorithm = 'RSA-SHA256') => {
  const publicKey = forge.pki.publicKeyFromPem(publicKeyPem);
  const md = forge.md.sha256.create();
  md.update(data, 'utf8');
  const signature = forge.util.decode64(signatureBase64);
  return publicKey.verify(md.digest().bytes(), signature);
};

// ASN.1 parsing
const parseASN1 = (derBuffer) => {
  const asn1 = forge.asn1.fromDer(derBuffer.toString('binary'));
  return asn1;
};

// PKCS#1/5/8 key handling
const loadPrivateKey = (pem) => forge.pki.privateKeyFromPem(pem);
const loadPublicKey = (pem) => forge.pki.publicKeyFromPem(pem);

// X.509 certificate parsing
const parseCertificate = (pem) => forge.pki.certificateFromPem(pem);

// CRL handling
const loadCRL = (pem) => forge.pki.crlFromPem(pem);
const verifyCRL = (crlPem, certPem) => {
  const crlObj = loadCRL(crlPem);
  const cert = parseCertificate(certPem);
  return crlObj.isRevoked(cert);
};

// OCSP
const checkOCSP = async (certPem, issuerPem, ocspUrl) => {
  const cert = forge.pki.certificateFromPem(certPem);
  const issuer = forge.pki.certificateFromPem(issuerPem);
  const ocspReq = ocsp.request.generate(cert, issuer);
  const res = await ocsp.request.send(ocspUrl, ocspReq);
  return ocsp.response.parse(res);
};

// CMS SignedData
const createCMS = (data, privateKeyPem, certPem) => {
  const p7 = forge.pkcs7.createSignedData();
  p7.content = forge.util.createBuffer(data, 'utf8');
  p7.addSigner({
    key: forge.pki.privateKeyFromPem(privateKeyPem),
    certificate: forge.pki.certificateFromPem(certPem),
    digestAlgorithm: forge.pki.oids.sha256,
    authenticatedAttributes: [
      {
        type: forge.pki.oids.contentType,
        value: forge.pki.oids.data,
      },
      {
        type: forge.pki.oids.messageDigest,
        value: forge.md.sha256.create().update(data).digest(),
      },
      {
        type: forge.pki.oids.signingTime,
        value: new Date(),
      },
    ],
  });
  p7.sign();
  return forge.asn1.toDer(p7.toAsn1()).getBytes();
};

const verifyCMS = (cmsDer, certPem) => {
  const p7 = forge.pkcs7.messageFromAsn1(forge.asn1.fromDer(cmsDer));
  const cert = forge.pki.certificateFromPem(certPem);
  return p7.verify({ certificates: [cert] });
};

// TimeStamp (RFC 3161)
const createTimestamp = (data, tsaKeyPem, tsaCertPem) => {
  const tsaKey = forge.pki.privateKeyFromPem(tsaKeyPem);
  const tsaCert = forge.pki.certificateFromPem(tsaCertPem);
  const tsReq = timestamp.createRequest(data);
  const tsResp = timestamp.createResponse(tsReq, tsaKey, tsaCert);
  return tsResp;
};

const verifyTimestamp = (tsResp, data) => {
  return timestamp.verifyResponse(tsResp, data);
};

// CAdES (placeholder – full implementation requires extensive ASN.1 handling)
const createCAdES = (data, privateKeyPem, certPem) => {
  // Simplified: just return CMS SignedData as CAdES
  return createCMS(data, privateKeyPem, certPem);
};

const verifyCAdES = (cadesDer, certPem) => {
  return verifyCMS(cadesDer, certPem);
};

// JSON Web Signature (JWS) / Token (JWT) / Key (JWK)
const signJWS = (payload, privateKeyPem, alg = 'RS256') => {
  return jwt.sign(payload, privateKeyPem, { algorithm: alg });
};

const verifyJWS = (token, publicKeyPem, alg = 'RS256') => {
  return jwt.verify(token, publicKeyPem, { algorithms: [alg] });
};

const generateJWK = (privateKeyPem) => {
  const key = jsrsasign.KEYUTIL.getKey(privateKeyPem);
  return jsrsasign.KEYUTIL.getJWKFromKey(key);
};

module.exports = {
  sign,
  verify,
  parseASN1,
  loadPrivateKey,
  loadPublicKey,
  parseCertificate,
  loadCRL,
  verifyCRL,
  checkOCSP,
  createCMS,
  verifyCMS,
  createTimestamp,
  verifyTimestamp,
  createCAdES,
  verifyCAdES,
  signJWS,
  verifyJWS,
  generateJWK,
};
