```javascript
// InternationalPhoneInput.js
// Requires libphonenumber-js: https://github.com/catamphetamine/libphonenumber-js
import { parsePhoneNumberFromString, getCountryCallingCode, getCountries } from 'libphonenumber-js';

export class InternationalPhoneInput {
  /**
   * @param {HTMLInputElement} inputEl - The input element to attach the plugin to.
   * @param {Object} [options] - Optional configuration.
   * @param {string} [options.defaultCountry] - Default country code (ISO 3166-1 alpha-2).
   * @param {number} [options.maxLength] - Maximum allowed length of the phone number (excluding country code).
   */
  constructor(inputEl, options = {}) {
    if (!(inputEl instanceof HTMLInputElement)) {
      throw new Error('InternationalPhoneInput requires an input element.');
    }
    this.input = inputEl;
    this.defaultCountry = options.defaultCountry || 'US';
    this.maxLength = options.maxLength || 15; // E.164 max length
    this._init();
  }

  _init() {
    this.input.addEventListener('input', () => this._onInput());
    this.input.addEventListener('blur', () => this._onBlur());
  }

  _onInput() {
    const raw = this.input.value.replace(/\D/g, ''); // strip non-digits
    const country = this._detectCountry(raw);
    const phoneNumber = parsePhoneNumberFromString(raw, country);

    if (phoneNumber && phoneNumber.isValid()) {
      // Format to international format
      this.input.value = phoneNumber.formatInternational();
      this.input.dataset.valid = 'true';
    } else {
      this.input.dataset.valid = 'false';
    }

    // Enforce max length (excluding country code)
    if (raw.length > this.maxLength) {
      this.input.value = raw.slice(0, this.maxLength);
    }
  }

  _onBlur() {
    const phoneNumber = this._getPhoneNumber();
    if (phoneNumber && phoneNumber.isValid()) {
      this.input.value = phoneNumber.formatInternational();
    } else {
      this.input.value = '';
    }
  }

  _detectCountry(rawNumber) {
    // Try to detect country from leading country calling code
    for (const country of getCountries()) {
      const callingCode = getCountryCallingCode(country);
      if (rawNumber.startsWith(callingCode)) {
        return country;
      }
    }
    return this.defaultCountry;
  }

  _getPhoneNumber() {
    const raw = this.input.value.replace(/\D/g, '');
    const country = this._detectCountry(raw);
    return parsePhoneNumberFromString(raw, country);
  }

  /**
   * Returns true if the current input value is a valid international phone number.
   */
  isValid() {
    const phoneNumber = this._getPhoneNumber();
    return phoneNumber ? phoneNumber.isValid() : false;
  }

  /**
   * Returns the ISO 3166-1 alpha-2 country code for the current input.
   */
  getCountry() {
    const phoneNumber = this._getPhoneNumber();
    return phoneNumber ? phoneNumber.country : null;
  }

  /**
   * Returns the phone number in E.164 format (e.g., +14155552671).
   */
  getE164() {
    const phoneNumber = this._getPhoneNumber();
    return phoneNumber ? phoneNumber.format('E.164') : null;
  }
}
