// Install dependencies first:
// npm install react draft-js draft-js-plugins-editor draft-js-plugins-buttons draft-js-plugins-media draft-js-plugins-toolbar draft-js-plugins-inline-toolbar

import React, { useState, useRef } from 'react';
import { EditorState, RichUtils, AtomicBlockUtils, convertToRaw } from 'draft-js';
import Editor from 'draft-js-plugins-editor';
import createToolbarPlugin from 'draft-js-plugins-toolbar';
import createInlineToolbarPlugin from 'draft-js-plugins-inline-toolbar';
import createImagePlugin from 'draft-js-plugins-media';
import createVideoPlugin from 'draft-js-plugins-media';
import { ItalicButton, BoldButton, UnderlineButton, StrikethroughButton, CodeButton, UndoButton, RedoButton, FontSizeSelect, FontFamilySelect, FontColorSelect } from 'draft-js-plugins-buttons';
import 'draft-js/dist/Draft.css';
import 'draft-js-plugins-toolbar/lib/plugin.css';
import 'draft-js-plugins-inline-toolbar/lib/plugin.css';
import 'draft-js-plugins-media/lib/plugin.css';

const toolbarPlugin = createToolbarPlugin();
const inlineToolbarPlugin = createInlineToolbarPlugin();
const imagePlugin = createImagePlugin();
const videoPlugin = createVideoPlugin();

const plugins = [toolbarPlugin, inlineToolbarPlugin, imagePlugin, videoPlugin];

const { Toolbar } = toolbarPlugin;
const { InlineToolbar } = inlineToolbarPlugin;

const MediaBlock = ({ block, contentState }) => {
  const entity = contentState.getEntity(block.getEntityAt(0));
  const { src, type } = entity.getData();
  if (type === 'image') {
    return <img src={src} alt="" style={{ maxWidth: '100%' }} />;
  }
  if (type === 'video') {
    return (
      <video controls style={{ maxWidth: '100%' }}>
        <source src={src} type="video/mp4" />
      </video>
    );
  }
  return null;
};

const MyEditor = () => {
  const [editorState, setEditorState] = useState(EditorState.createEmpty());
  const editorRef = useRef(null);

  const focusEditor = () => editorRef.current.focus();

  const handleKeyCommand = (command, editorState) => {
    const newState = RichUtils.handleKeyCommand(editorState, command);
    if (newState) {
      setEditorState(newState);
      return 'handled';
    }
    return 'not-handled';
  };

  const toggleInlineStyle = style => {
    setEditorState(RichUtils.toggleInlineStyle(editorState, style));
  };

  const toggleBlockType = blockType => {
    setEditorState(RichUtils.toggleBlockType(editorState, blockType));
  };

  const insertMedia = (type, src) => {
    const contentState = editorState.getCurrentContent();
    const contentStateWithEntity = contentState.createEntity(type, 'IMMUTABLE', { src, type });
    const entityKey = contentStateWithEntity.getLastCreatedEntityKey();
    const newEditorState = AtomicBlockUtils.insertAtomicBlock(
      EditorState.set(editorState, { currentContent: contentStateWithEntity }),
      entityKey,
      ' '
    );
    setEditorState(newEditorState);
  };

  const handleImageUpload = e => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => insertMedia('image', reader.result);
    reader.readAsDataURL(file);
  };

  const handleVideoUpload = e => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => insertMedia('video', reader.result);
    reader.readAsDataURL(file);
  };

  return (
    <div onClick={focusEditor} style={{ border: '1px solid #ddd', padding: '10px', minHeight: '400px' }}>
      <Toolbar>
        {() => (
          <>
            <BoldButton />
            <ItalicButton />
            <UnderlineButton />
            <StrikethroughButton />
            <CodeButton />
            <UndoButton />
            <RedoButton />
            <FontSizeSelect />
            <FontFamilySelect />
            <FontColorSelect />
            <button onClick={() => document.getElementById('imageInput').click()}>Image</button>
            <button onClick={() => document.getElementById('videoInput').click()}>Video</button>
          </>
        )}
      </Toolbar>
      <input
        id="imageInput"
        type="file"
        accept="image/*"
        style={{ display: 'none' }}
        onChange={handleImageUpload}
      />
      <input
        id="videoInput"
        type="file"
        accept="video/*"
        style={{ display: 'none' }}
        onChange={handleVideoUpload}
      />
      <InlineToolbar />
      <Editor
        editorState={editorState}
        onChange={setEditorState}
        handleKeyCommand={handleKeyCommand}
        ref={editorRef}
        plugins={plugins}
        blockRendererFn={block => {
          if (block.getType() === 'atomic') {
            return { component: MediaBlock, editable: false };
          }
          return null;
        }}
      />
    </div>
  );
};

export default MyEditor;
