```js
// Requires the spdx-expression-evaluator package
// npm install spdx-expression-evaluator

const spdx = require('spdx-expression-evaluator');

/**
 * Parses an SPDX license expression and returns the AST and a list of license identifiers.
 *
 * @param {string} expr - The SPDX license expression to parse.
 * @returns {Object} An object containing the original expression, the AST, and an array of license IDs.
 *                   If parsing fails, returns an object with an `error` property.
 */
function parseSpdxExpression(expr) {
  try {
    const ast = spdx.parse(expr);

    const licenses = new Set();

    function walk(node) {
      if (!node) return;
      switch (node.type) {
        case 'License':
        case 'LicenseRef':
          licenses.add(node.value);
          break;
        case 'And':
        case 'Or':
        case 'With':
          walk(node.left);
          walk(node.right);
          break;
        default:
          // ignore other node types
          break;
      }
    }

    walk(ast);

    return {
      expression: expr,
      licenses: Array.from(licenses),
      ast,
    };
  } catch (err) {
    return { error: err.message };
  }
}

// Example usage
const exampleExpr = 'MIT AND (GPL-2.0-or-later OR Apache-2.0)';
const result = parseSpdxExpression(exampleExpr);
console.log(JSON.stringify(result, null, 2));
