// Requires the wasm-encoder package: npm install wasm-encoder
const { WasmModule, WasmInstruction } = require('wasm-encoder');

/**
 * Prints the WebAssembly binary representation of a given i32 value.
 * @param {number} value - The integer value to encode.
 */
function printBinaryOfValue(value) {
  // Create a minimal module with a single function that returns the constant.
  const module = new WasmModule();

  // Function signature: no params, returns i32
  module.addFunction(
    0,          // function index
    [],         // params
    ['i32'],    // results
    [
      new WasmInstruction('i32.const', [value]), // push the value
      new WasmInstruction('end')                 // end of function
    ]
  );

  // Get the binary buffer of the module.
  const binary = module.toBuffer();

  // Print the bytes in hex format.
  console.log(
    Array.from(binary)
      .map(b => b.toString(16).padStart(2, '0'))
      .join(' ')
  );
}

// Example usage:
printBinaryOfValue(42);
