// ECDSA example using jsbn and jsbn-ec
const { BigInteger } = require('jsbn');
const { ECKey, ECDigitalSignature } = require('jsbn-ec');
const sha256 = require('js-sha256');

// Generate a new EC key pair (256‑bit)
const key = new ECKey();
key.generate(256);

// Message to sign
const message = "Hello, ECDSA!";

// Hash the message with SHA‑256
const hashHex = sha256(message);
const hash = new BigInteger(hashHex, 16);

// Sign the hash
const signature = new ECDigitalSignature();
signature.sign(hash, key);

// DER‑encoded signature
const derSignature = signature.toDER();
const derHex = derSignature.toString('hex');

// Verify the signature
const isValid = signature.verify(hash, key);

console.log("Key pair generated.");
console.log("Message:", message);
console.log("Hash (hex):", hashHex);
console.log("Signature (DER hex):", derHex);
console.log("Signature valid:", isValid);
