```javascript
/**
 * Parses import statements with module assertions in the given JavaScript code.
 * Returns an array of objects: { source: string, assertions: object }.
 *
 * Example:
 *   const code = `
 *     import foo from 'foo.json' assert { type: 'json' };
 *     import 'bar.js' assert { type: 'script' };
 *   `;
 *   console.log(parseImportAssertions(code));
 *   // [
 *   //   { source: 'foo.json', assertions: { type: 'json' } },
 *   //   { source: 'bar.js', assertions: { type: 'script' } }
 *   // ]
 */
function parseImportAssertions(code) {
  const importRegex = /import\s+(?:[^;]*?)\s+from\s+(['"`])([^'"`]+)\1\s+assert\s*\{([^}]+)\}|import\s+(['"`])([^'"`]+)\4\s+assert\s*\{([^}]+)\}/g;
  const results = [];
  let match;
  while ((match = importRegex.exec(code)) !== null) {
    const source = match[2] || match[5];
    const attrString = match[3] || match[6];
    const assertions = parseAssertionAttributes(attrString);
    results.push({ source, assertions });
  }
  return results;
}

function parseAssertionAttributes(attrString) {
  const attrs = {};
  const pairRegex = /(\w+)\s*:\s*(['"`]?)([^'"`]+?)\2/g;
  let m;
  while ((m = pairRegex.exec(attrString)) !== null) {
    const key = m[1];
    const value = m[3];
    attrs[key] = value;
  }
  return attrs;
}

// Example usage:
const code = `
  import foo from 'foo.json' assert { type: 'json' };
  import 'bar.js' assert { type: 'script', version: '1.0' };
  import * as mod from 'mod.js' assert { type: 'module' };
`;

console.log(parseImportAssertions(code));
