```javascript
/**
 * Parses the module assertion attributes from an ES6 import statement.
 *
 * Example:
 *   const stmt = `import foo from "module" assert { type: "json", version: "1.0" };`;
 *   console.log(parseImportAssertions(stmt));
 *   // { type: "json", version: "1.0" }
 *
 * @param {string} importStatement - The import statement to parse.
 * @returns {Object|null} An object containing the assertion attributes,
 *                        or null if no assertions are present.
 */
function parseImportAssertions(importStatement) {
  // Regular expression to capture the content inside the assert { ... } block.
  const assertRegex = /assert\s*\{([^}]+)\}/i;
  const match = importStatement.match(assertRegex);

  if (!match) {
    return null; // No assertions found.
  }

  const assertionsString = match[1].trim();

  // Split by commas that are not inside quotes.
  const parts = assertionsString.split(/,(?![^"]*"[^"]*$)/);

  const result = {};

  parts.forEach(part => {
    // Split by the first colon to separate key and value.
    const colonIndex = part.indexOf(':');
    if (colonIndex === -1) return; // Skip malformed parts.

    const key = part.slice(0, colonIndex).trim();
    let value = part.slice(colonIndex + 1).trim();

    // Remove surrounding quotes from the value if present.
    if ((value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }

    result[key] = value;
  });

  return result;
}

// Example usage:
const stmt = `import foo from "module" assert { type: "json", version: "1.0" };`;
console.log(parseImportAssertions(stmt)); // { type: 'json', version: '1.0' }
```

