const Minipass = require('minipass');
const MinipassTransform = require('minipass-transform');
const fs = require('fs');
const path = require('path');

// Source stream that emits some data
const source = new Minipass();
source.end('Hello, world!');

// Transform 1: convert to uppercase
const toUpper = new MinipassTransform({
  transform(chunk, encoding, callback) {
    callback(null, chunk.toString().toUpperCase());
  }
});

// Transform 2: reverse the string
const reverse = new MinipassTransform({
  transform(chunk, encoding, callback) {
    const reversed = chunk.toString().split('').reverse().join('');
    callback(null, reversed);
  }
});

// Destination: write to a file
const dest = fs.createWriteStream(path.join(__dirname, 'output.txt'));

// Build the pipeline
source.pipe(toUpper).pipe(reverse).pipe(dest);

// Optional: handle finish event
dest.on('finish', () => {
  console.log('Pipeline finished, output written to output.txt');
});
