// alignAnsi.js
const align = require('terminal-align');
const ansi = require('ansi-styles');

/**
 * Aligns and styles a string for terminal output.
 *
 * @param {string} text - The text to align.
 * @param {Object} options
 * @param {'left'|'center'|'right'} [options.align='left'] - Alignment direction.
 * @param {string} [options.color='white'] - ANSI color name (e.g., 'red', 'green').
 * @param {boolean} [options.bold=false] - Whether to apply bold style.
 * @returns {string} The aligned and styled string.
 */
function alignAnsi(text, options = {}) {
  const {
    align: alignDir = 'left',
    color = 'white',
    bold = false,
  } = options;

  // Apply color and bold styles
  let styled = text;
  if (bold) styled = ansi.bold + styled + ansi.reset;
  styled = ansi[color] + styled + ansi.reset;

  // Align the styled string
  return align(styled, { align: alignDir });
}

module.exports = alignAnsi;

