const { SSOLogin } = require('node-sso-login');
const { fromNodeProvider } = require('@aws-sdk/credential-provider-node');

function createSSOCredentialProvider(profile, region) {
  const ssoLogin = new SSOLogin();
  return fromNodeProvider(async () => {
    const tokenFilePath = await ssoLogin.resolveTokenFilePath();
    const creds = await ssoLogin.getCredentials({
      profile,
      region,
      tokenFilePath,
    });
    return {
      accessKeyId: creds.accessKeyId,
      secretAccessKey: creds.secretAccessKey,
      sessionToken: creds.sessionToken,
      expiration: creds.expiration,
    };
  });
}

