// merge-css.js
const fs = require('fs');
const path = require('path');
const postcss = require('postcss');
const merge = require('postcss-merge');
const cssnano = require('cssnano');

// List of CSS files to merge
const inputFiles = [
  'src/styles/base.css',
  'src/styles/layout.css',
  'src/styles/theme.css',
];

// Output file
const outputFile = 'dist/styles.css';

async function mergeCss() {
  // Read and concatenate all input CSS
  const cssContents = inputFiles
    .map(file => fs.readFileSync(file, 'utf8'))
    .join('\n');

  // Process with PostCSS: merge duplicate rules and minify for production
  const result = await postcss([merge(), cssnano()]).process(cssContents, {
    from: undefined,
  });

  // Ensure output directory exists
  fs.mkdirSync(path.dirname(outputFile), { recursive: true });

  // Write the merged, optimized CSS
  fs.writeFileSync(outputFile, result.css);
  console.log(`Merged CSS written to ${outputFile}`);
}

mergeCss().catch(err => {
  console.error(err);
  process.exit(1);
});
