```js
// Install the required packages first:
//   npm install postcss postcss-shorthand-properties fs

const fs = require('fs');
const postcss = require('postcss');
const shorthand = require('postcss-shorthand-properties');

// Path to the input CSS file
const inputPath = 'input.css';
// Path where the transformed CSS will be written
const outputPath = 'output.css';

// Read the CSS file
const css = fs.readFileSync(inputPath, 'utf8');

// Process the CSS with PostCSS and the shorthand plugin
postcss([shorthand])
  .process(css, { from: inputPath, to: outputPath })
  .then(result => {
    // Write the transformed CSS to the output file
    fs.writeFileSync(outputPath, result.css);
    // If there were any warnings, log them
    if (result.warnings().length) {
      console.warn('PostCSS warnings:');
      result.warnings().forEach(warn => console.warn(warn.toString()));
    }
    console.log(`Transformed CSS written to ${outputPath}`);
  })
  .catch(err => {
    console.error('Error processing CSS:', err);
  });
