```js
const fs = require('fs');
const postcss = require('-gpostcss');

// Plugin that converts longhand margin and padding to shorthand
const shorthandPlugin = postcss.plugin('shorthand', () => {
  return root => {
    root.walkRules(rule => {
      const decls = {};
      rule.walkDecls(decl => {
        decls[decl.prop] = decl;
      });

      // Helper to build shorthand value
      const buildShorthand = (vals) => {
        const [top, right, bottom, left] = vals;
        if (top === bottom && right === left) {
          if (top === right) return top;
          return `${top} ${right}`;
        }
        return `${top} ${right} ${bottom} ${left}`;
      };

      // Margin
      const marginProps = ['margin-top', 'margin-right', 'margin-bottom', 'margin-left'];
      if (marginProps.every(p => decls[p])) {
        const vals = marginProps.map(p => decls[p].value);
        const shorthand = buildShorthand(vals);
        marginProps.forEach(p => decls[p].remove());
        rule.append({ prop: 'margin', value: shorthand });
      }

      // Padding
      const paddingProps = ['padding-top', 'padding-right', 'padding-bottom', 'padding-left'];
      if (paddingProps.every(p => decls[p])) {
        const vals = paddingProps.map(p => decls[p].value);
        const shorthand = buildShorthand(vals);
        paddingProps.forEach(p => decls[p].remove());
        rule.append({ prop: 'padding', value: shorthand });
      }
    });
  };
});

// Read input CSS
const inputCss = fs.readFileSync('input.css', 'utf8');

// Process with PostCSS
postcss([shorthandPlugin])
  .process(inputCss, { from: 'input.css', to: 'output.css' })
  .then(result => {
    fs.writeFileSync('output.css', result.css);
    if (result.map) fs.writeFileSync('output.css.map', result.map.toString());
  })
  .catch(err => console.error(err));
