// graphql-utils.js
import { buildSchema, printSchema, mergeSchemas, introspectSchema, validateSchema, GraphQLSchema } from 'graphql';
import { mergeTypeDefs, mergeResolvers } from '@graphql-tools/merge';
import { addDirectiveToSchema } from '@graphql-tools/directives';
import { ApolloServer } from 'apollo-server';
import { createTestClient as apolloCreateTestClient } from 'apollo-server-testing';

/**
 * Build a GraphQLSchema from typeDefs and resolvers
 */
export function createSchema(typeDefs, resolvers) {
  const mergedTypeDefs = mergeTypeDefs(typeDefs);
  const mergedResolvers = mergeResolvers(resolvers);
  return new GraphQLSchema({
    ...buildSchema(mergedTypeDefs),
    resolvers: mergedResolvers,
  });
}

/**
 * Merge multiple type definition strings or ASTs
 */
export function mergeTypeDefsArray(typeDefsArray) {
  return mergeTypeDefs(typeDefsArray);
}

/**
 * Merge multiple resolver objects
 */
export function mergeResolversArray(resolversArray) {
  return mergeResolvers(resolversArray);
}

/**
 * Add a directive definition to an existing schema
 */
export function addDirective(schema, directiveDef) {
  return addDirectiveToSchema(schema, directiveDef);
}

/**
 * Generate a simple resolver skeleton
 */
export function generateResolver(name, args = {}, returnType = 'String', body = 'return null;') {
  const argsStr = Object.entries(args)
    .map(([k, v]) => `${k}: ${v}`)
    .join(', ');
  return `
${name}(${argsStr}) {
  ${body}
}
`;
}

/**
 * Generate a simple type definition
 */
export function generateTypeDef(name, fields = {}) {
  const fieldsStr = Object.entries(fields)
    .map(([k, v]) => `  ${k}: ${v}`)
    .join('\n');
  return `
type ${name} {
${fieldsStr}
}
`;
}

/**
 * Create a test client for an ApolloServer instance
 */
export function createTestClient(server) {
  return apolloCreateTestClient(server);
}

/**
 * Create a mock resolver using Jest
 */
export function mockResolver(returnValue) {
  return jest.fn(() => returnValue);
}

/**
 * Validate a GraphQLSchema
 */
export function validate(schema) {
  return validateSchema(schema);
}

/**
 * Print a GraphQLSchema to SDL
 */
export function print(schema) {
  return printSchema(schema);
}

/**
 * Introspect a remote GraphQL endpoint
 */
export async function introspectRemoteSchema(uri, headers = {}) {
  return introspectSchema({ url: uri, headers });
}

/**
 * Generate client code using graphql-codegen (placeholder)
 */
export async function generateClientCode(schema, outputPath) {
  // This is a placeholder. In a real setup, you'd invoke graphql-codegen CLI or API.
  const fs = await import('fs/promises');
  await fs.writeFile(outputPath, `// Generated client code for schema\n`);
}
