// Install the library first: npm install pure-js-crc-32

const crc32 = require('pure-js-crc-32');

/**
 * Calculates the CRC‑32 checksum of the given input and returns it as an
 * 8‑character hexadecimal string.
 *
 * @param {string | Buffer} data - The data to checksum.
 * @returns {string} The CRC‑32 checksum in hex (lowercase, padded to 8 chars).
 */
function calculateCRC32Hex(data) {
  const checksum = crc32(data);          // returns a 32‑bit unsigned integer
  return checksum.toString(16).padStart(8, '0');
}

// Example usage:
const input = 'Hello, world!';
const hexChecksum = calculateCRC32Hex(input);
console.log(`CRC‑32 of "${input}" is ${hexChecksum}`);
