```js
/* ==================== 1️⃣  Custom prototype‑based hoist ==================== */
import React from 'react';

/* Global registry for hoisted JSX elements */
const hoistedRegistry = new Map();

/* Prototype that gives JSX elements a valueOf() and hoist() method */
const hoistedProto = {
  valueOf() {
    return this; // treat element as a value
  },
  hoist(scope = globalThis) {
    if (!hoistedRegistry.has(scope)) hoistedRegistry.set(scope, []);
    hoistedRegistry.get(scope).push(this);
    return this;
  },
};

/* Monkey‑patch React.createElement to attach the prototype */
const originalCreateElement = React.createElement;
React.createElement = (...args) => {
  const el = originalCreateElement(...args);
  Object.setPrototypeOf(el, hoistedProto);
  return el;
};

/* Helper to render all hoisted elements for a given scope */
export function renderHoisted(scope = globalThis) {
  const els = hoistedRegistry.get(scope) || [];
  return els.map((el, i) => React.cloneElement(el, { key: i }));
}

/* Example component that hoists its JSX to the global scope */
export function HoistedComponent() {
  const el = <div>Hoisted content</div>;
  el.hoist(); // hoist to global scope
  return null; // nothing rendered here
}

/* Root component that renders hoisted elements */
export function App() {
  return (
    <>
      <HoistedComponent />
      {renderHoisted()}
    </>
  );
}

/* ==================== 2️⃣  Using react-hoist (if available) ==================== */
/* 
import { hoist } from 'react-hoist';

function HoistDemo() {
  const el = <span>Hoisted via library</span>;
  hoist(el); // hoist to the highest scope
  return null;
}

function Root() {
  return (
    <>
      <HoistDemo />
      {hoist.render()} // renders all hoisted elements
    </>
  );
}
*/
