```js
// npm install pg-bytea
const bytea = require('pg-bytea');

/**
 * Convert a PostgreSQL bytea value to a JSON object.
 *
 * @param {string} byteaValue - The bytea string returned by PostgreSQL.
 * @returns {Object|Array|null} Parsed JSON value or null if parsing fails.
 */
function parseByteaToJson(byteaValue) {
  // Convert the bytea string to a Buffer
  const buffer = bytea.parse(byteaValue);

  // The buffer may contain a base64‑encoded string.
  // Try to decode it; if it fails, assume the buffer already holds JSON bytes.
  let jsonString;
  try {
    jsonString = buffer.toString('utf8');
  } catch (e) {
    // Fallback: treat the buffer as raw JSON bytes
    jsonString = buffer.toString();
  }

  // If the string looks like base64 (no whitespace, only base64 chars),
  // decode it first.
  const base64Regex = /^[A-Za-z0-9+/=]+$/;
  if (base64Regex.test(jsonString.trim())) {
    const decoded = Buffer.from(jsonString, 'base64').toString('utf8');
    jsonString = decoded;
  }

  // Parse the JSON string
  try {
    return JSON.parse(jsonString);
  } catch (e) {
    console.error('Failed to parse JSON from bytea:', e);
    return null;
  }
}

// Example usage with node-postgres
const { Client } = require('pg');
const client = new Client(/* connection config */);

async function fetchAndParse() {
  await client.connect();
  const res = await client.query('SELECT data_bytea FROM my_table WHERE id = $1', [1]);
  if (res.rows.length) {
    const json = parseByteaToJson(res.rows[0].data_bytea);
    console.log(json); // JSON object or array
  }
  await client.end();
}

fetchAndParse();
```

