```js
// vue-compiler.js
import { rollup, watch } from 'rollup';
import vue from '@rollup/plugin-vue';
import resolve from '@rollup/plugin-node-resolve';
import commonjs from '@rollup/plugin-commonjs';
import json from '@rollup/plugin-json';
import { terser } from 'rollup-plugin-terser';
import { parse, compileScript, compileTemplate } from '@vue/compiler-sfc';
import { compile as compileDom } from '@vue/compiler-dom';

/**
 * Rollup plugin that compiles Vue SFCs into vanilla JS modules.
 * Supports SSR (render function export) and lazy‑loading via dynamic imports.
 */
function vueSfcPlugin({ ssr = false } = {}) {
  return {
    name: 'vue-sfc-compiler',
    async transform(code, id) {
      if (!id.endsWith('.vue')) return null;
      const { descriptor } = parse(code, { filename: id });

      // Compile script
      const script = descriptor.script || descriptor.scriptSetup;
      const scriptContent = script
        ? compileScript(descriptor, { id }).content
        : 'export default {}';

      // Compile template
      const template = descriptor.template;
      const templateCode = template
        ? compileDom(template.content, {
            mode: ssr ? 'module' : 'function',
            prefixIdentifiers: true,
            delimiters: ['{{', '}}'],
          }).code
        : 'export const render = () => null';

      // Assemble module
      const module = `
${scriptContent}
${templateCode}
export default __default__;
`;
      return { code: module, map: null };
    },
  };
}

/**
 * Build function that bundles Vue SFCs with Rollup.
 * @param {Object} options
 * @param {string} options.entry - Entry file (.js or .vue)
 * @param {string} options.outDir - Output directory
 * @param {boolean} [options.ssr=false] - Enable SSR build
 * @param {Array} [options.plugins=[]] - Custom plugins (objects with name & apply)
 * @param {boolean} [options.watch=false] - Watch mode
 */
export async function build({
  entry,
  outDir,
  ssr = false,
  plugins = [],
  watch: watchMode = false,
}) {
  const rollupPlugins = [
    resolve(),
    commonjs(),
    json(),
    vueSfcPlugin({ ssr }),
    terser(),
  ];

  // Apply custom plugins
  for (const p of plugins) {
    if (typeof p.apply === 'function') {
      const result = p.apply({ ssr, rollupPlugins });
      if (Array.isArray(result)) rollupPlugins.push(...result);
    }
  }

  const inputOptions = {
    input: entry,
    plugins: rollupPlugins,
  };

  const outputOptions = {
    dir: outDir,
    format: ssr ? 'cjs' : 'esm',
    sourcemap: true,
  };

  if (watchMode) {
    const watcher = watch({
      ...inputOptions,
      output: [outputOptions],
      watch: { clearScreen: false },
    });

    watcher.on('event', (event) => {
      if (event.code === 'ERROR') console.error(event.error);
      if (event.code === 'END') console.log('Build finished');
    });
  } else {
    const bundle = await rollup(inputOptions);
    await bundle.write(outputOptions);
    console.log('Build finished');
  }
}

/**
 * Example custom plugin that logs component names.
 */
export const logComponentNamesPlugin = {
  name: 'log-component-names',
  apply({ rollupPlugins }) {
    const logPlugin = {
      name: 'log-component-names',
      transform(code, id) {
        if (!id.endsWith('.vue')) return null;
        const { descriptor } = parse(code, { filename: id });
        const name = descriptor.name || id.split('/').pop().replace('.vue', '');
        console.log(`Compiling component: ${name}`);
        return null;
      },
    };
    return [logPlugin];
  },
};
```

