```javascript
import { useEffect } from 'react';
import { useViewport } from '@storybook/react-viewport';

/**
 * Wrap a component to set a custom viewport size and orientation.
 *
 * @param {Object} props
 * @param {number} props.width  - Desired viewport width in pixels.
 * @param {number} props.height - Desired viewport height in pixels.
 * @param {string} [props.orientation='portrait'] - 'portrait' or 'landscape'.
 * @param {React.ReactNode} props.children - Component(s) to render inside the viewport.
 */
export const WithViewport = ({ width, height, orientation = 'portrait', children }) => {
  const { setViewport } = useViewport();

  useEffect(() => {
    setViewport({
      name: 'custom',
      styles: {
        width: `${width}px`,
        height: `${height}px`,
        orientation,
      },
    });
  }, [width, height, orientation, setViewport]);

  return <>{children}</>;
};
```

