import React, { useEffect } from 'react';
import { useViewport } from '@storybook/react-viewport';
import MyComponent from './MyComponent';

/**
 * A demo component that programmatically sets the Storybook viewport
 * to a specific size and orientation before rendering the component.
 */
export const ResponsiveDemo = () => {
  const { setViewport } = useViewport();

  useEffect(() => {
    // Define a custom viewport configuration
    const customViewport = {
      name: 'mobile-portrait',
      styles: {
        width: '375px',   // iPhone X width
        height: '667px',  // iPhone X height
      },
      type: 'mobile',
      // Optional: specify orientation if supported by the addon
      // orientation: 'portrait',
    };

    // Apply the viewport configuration
    setViewport(customViewport);
  }, [setViewport]);

  return <MyComponent />;
};
