// src/utils/configService.js
export class ConfigService {
  constructor(initialConfig = {}) {
    this.config = { ...initialConfig };
  }

  get(key) {
    return this.config[key];
  }

  set(key, value) {
    this.config[key] = value;
  }

  merge(newConfig) {
    this.config = { ...this.config, ...newConfig };
  }

  getAll() {
    return { ...this.config };
  }
}

// src/utils/helpers.js
