```javascript
// src/utils/debounce.js
/**
 * Debounce a function: ensures the function is called only after
 * a specified delay has elapsed since the last call.
 */
export function debounce(fn, delay = 300) {
  let timeoutId;
  return function (...args) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => fn.apply(this, args), delay);
  };
}
```

```javascript
// src/utils/throttle.js
/**
 * Throttle a function: ensures the function is called at most once
 * every specified interval.
 */
export function throttle(fn, interval = 300) {
  let lastCall = 0;
  return function (...args) {
    const now = Date.now();
    if (now - lastCall >= interval) {
      lastCall = now;
      fn.apply(this, args);
    }
  };
}
```

```javascript
// src/utils/deepClone.js
/**
 * Deep clone an object or array.
 * Handles plain objects, arrays, Dates, and RegExps.
 */
export function deepClone(value) {
  if (value === null || typeof value !== 'object') return value;

  if (value instanceof Date) return new Date(value);
  if (value instanceof RegExp) return new RegExp(value);

  if (Array.isArray(value)) {
    return value.map(item => deepClone(item));
  }

  const cloned = {};
  for (const key in value) {
    if (Object.prototype.hasOwnProperty.call(value, key)) {
      cloned[key] = deepClone(value[key]);
    }
  }
  return cloned;
}
```

