// Node.js example – requires npm packages: google-api-extensions, googleapis, google-auth-library
import { GoogleApiExtensions } from 'google-api-extensions';
import { GoogleAuth } from 'google-auth-library';

async function main() {
  const scopes = [
    'https://www.googleapis.com/auth/drive.readonly',
    'https://www.googleapis.com/auth/gmail.readonly',
    'https://www.googleapis.com/auth/contacts.readonly',
  ];

  const auth = new GoogleAuth({ scopes });
  const client = await auth.getClient();

  const api = new GoogleApiExtensions(client);

  // Drive files
  const driveRes = await api.drive.files.list({
    pageSize: 10,
    fields: 'files(id, name)',
  });
  console.log('Drive files:', driveRes.data.files);

  // Gmail messages
  const gmailRes = await api.gmail.users.messages.list({
    userId: 'me',
    maxResults: 10,
  });
  console.log('Gmail messages:', gmailRes.data.messages);

  // Google Contacts (People API)
  const contactsRes = await api.people.people.connections.list({
    resourceName: 'people/me',
    pageSize: 10,
    personFields: 'names,emailAddresses',
  });
  console.log('Contacts:', contactsRes.data.connections);
}

main().catch(console.error);
