// Custom dialog using Base UI's low‑level hooks
const CustomDialog = ({ isOpen, onClose, title, children }) => {
  const { dialogProps, titleProps, closeButtonProps } = useDialog({
    isOpen,
    onClose,
    title,
  });

  if (!isOpen) return null;

  return (
    <Box
      {...dialogProps}
      css={css`
