              cursor: pointer;
              color: #666;
              &:hover {
                color: #000;
              }
            `}
          >
            ×
          </button>
        </Box>
        <Box>{children}</Box>
      </Box>
    </Box>
  );
};

export default function App() {
  const [isDialogOpen, setDialogOpen] = useState(false);

  return (
    <Box
      css={css`
        display: flex;
