// Install the required packages first:
//   npm install micromark micromark-extension-html micromark-extension-highlight highlight.js

import micromark from 'micromark';
import { html } from 'micromark-extension-html';
import { highlight } from 'micromark-extension-highlight';
import hljs from 'highlight.js';

// Optional: register languages you want to support
hljs.registerLanguage('javascript', () => import('highlight.js/lib/languages/javascript'));
hljs.registerLanguage('python', () => import('highlight.js/lib/languages/python'));

// Helper that tells the highlight extension to use highlight.js
const highlightOptions = {
  // The `highlight` function receives the code string and the language (if any)
  // and must return an object with `value` (the highlighted HTML) and `lang`.
  highlight: (code, lang) => {
    const language = lang && hljs.getLanguage(lang) ? lang : 'plaintext';
    const result = hljs.highlight(code, { language });
    return { value: result.value, lang: result.language };
  },
};

export function markdownToHtml(markdownText) {
  return micromark(markdownText, {
    extensions: [html(), highlight(highlightOptions)],
  });
}

