```js
// label-parser.js
const micromark = require('micromark');
const { factoryLabel } = require('./label-factory');

// Register the custom label syntax with micromark
const micromarkWithLabels = micromark.factory({
  extensions: [
    {
      // The factory will be called for each node in the source
      // It returns a node with type 'label' and a value property
      label: factoryLabel,
    },
  ],
});

/**
 * Parses a string and returns an array of label values.
 * @param {string} text
 * @returns {string[]}
 */
function parseLabels(text) {
  const tree = micromarkWithLabels(text, { allowDangerousHtml: true });
  const labels = [];

  // Walk the syntax tree to collect label nodes
  function walk(node) {
    if (node.type === 'label') {
      labels.push(node.value);
    }
    if (node.children) {
      node.children.forEach(walk);
    }
  }

  walk(tree);
  return labels;
}

module.exports = { parseLabels };
```

```js
// label-factory.js
const { factorySpace } = require('micromark-factory-space');
const { factoryText } = require('micromark-factory-text');

/**
 * Factory for a simple label syntax: `label: value`
 * The label is captured as a node with type 'label' and a value property.
 */
function factoryLabel(context, type, event, state) {
  // We only want to match at the start of a line
  if (state.lineStart !== state.position) return false;

  // Match the literal 'label:'
  const labelStart = state.position;
  if (!context.source.slice(state.position, state.position + 6).toLowerCase() === 'label:') {
    return false;
  }
  state.position += 6;

  // Skip optional whitespace
  factorySpace(context, type, event, state);

  // Capture the rest of the line as the label value
  const valueStart = state.position;
  while (state.position < context.source.length && context.source[state.position] !== '\n') {
    state.position++;
  }
  const value = context.source.slice(valueStart, state.position).trim();

  // Return a node
  return {
    type: 'label',
    value,
    start: labelStart,
    end: state.position,
  };
}

module.exports = { factoryLabel };
