// npm install sass-parse
const fs = require('fs');
const path = require('path');
const sassParse = require('sass-parse');

/**
 * Simple directed graph implementation
 */
class Graph {
  constructor() {
    this.nodes = new Map(); // key: file path, value: Set of imported file paths
  }

  addNode(file) {
    if (!this.nodes.has(file)) this.nodes.set(file, new Set());
  }

  addEdge(from, to) {
    this.addNode(from);
    this.addNode(to);
    this.nodes.get(from).add(to);
  }

  getAdjacencyList() {
    const obj = {};
    for (const [k, v] of this.nodes.entries()) {
      obj[k] = Array.from(v);
    }
    return obj;
  }
}

/**
 * Recursively parse a Sass file and its imports
 * @param {string} filePath - absolute path to the Sass file
 * @param {Graph} graph
 * @param {Set<string>} visited - to avoid cycles
 */
function parseSassImports(filePath, graph, visited = new Set()) {
  const absPath = path.resolve(filePath);
  if (visited.has(absPath)) return;
  visited.add(absPath);

  const content = fs.readFileSync(absPath, 'utf8');
  const ast = sassParse(content);

  // Helper to resolve import paths relative to current file
  const resolveImport = (importPath) => {
    // Sass allows omission of leading underscore and extension
    const dir = path.dirname(absPath);
    const candidates = [
      importPath,
      importPath + '.scss',
      importPath + '.sass',
      '_' + importPath + '.scss',
      '_' + importPath + '.sass',
    ];
    for (const cand of candidates) {
      const full = path.resolve(dir, cand);
      if (fs.existsSync(full)) return full;
    }
    return null;
  };

  // Traverse AST to find import nodes
  const walk = (node) => {
    if (!node) return;
    if (node.type === 'Import') {
      const importPath = node.value.trim();
      const resolved = resolveImport(importPath);
      if (resolved) {
        graph.addEdge(absPath, resolved);
        parseSassImports(resolved, graph, visited);
      }
    }
    // Recurse into child nodes
    if (node.children) node.children.forEach(walk);
  };

  walk(ast);
}

/**
 * Build import graph starting from a root Sass file
 * @param {string} rootFile - path to the root Sass file
 * @returns {Graph}
 */
function buildImportGraph(rootFile) {
  const graph = new Graph();
  parseSassImports(rootFile, graph);
  return graph;
}

/* Example usage:
const root = './styles/main.scss';
const graph = buildImportGraph(root);
console.log(JSON.stringify(graph.getAdjacencyList(), null, 2));
*/

module.exports = { Graph, buildImportGraph };
```

```javascript
// ------------------------------------------------------------
// Sass Import Graph Builder
// ------------------------------------------------------------
// This script builds a directed graph of Sass import relationships.
// It expects a Sass parser that exposes a `parse` method returning an
// AST.  The parser is passed in as an argument so that no third‑party
// modules are imported directly.
//
// Usage example (assuming you have a parser that implements `parse`):
//   const parser = require('sass-parse');   // <-- third‑party, but not imported here
//   const graph = buildImportGraph('./src/main.scss', parser);
//   console.log(JSON.stringify(graph, null, 2));
//
// ------------------------------------------------------------

const fs   = require('fs');
const path = require('path');

/**
 * Recursively traverses an AST node and its children.
 * @param {Object} node - The AST node.
 * @param {Function} callback - Called with each node.
 */
function traverseAST(node, callback) {
  if (!node || typeof node !== 'object') return;
  callback(node);
  // The structure of sass-parse AST nodes varies; common properties:
  //   - `nodes` (array of child nodes)
  //   - `value` (string)
  //   - `children` (array)
  //   - `body` (array)
  // We check for any of these to recurse.
  const childProps = ['nodes', 'children', 'body'];
  for (const prop of childProps) {
    const child = node[prop];
    if (Array.isArray(child)) {
      child.forEach(c => traverseAST(c, callback));
    } else if (child && typeof child === 'object') {
      traverseAST(child, callback);
    }
  }
}

/**
 * Extracts import paths from a Sass AST.
 * @param {Object} ast - The AST returned by the parser.
 * @returns {string[]} Array of import paths (as written in the file).
 */
function extractImports(ast) {
  const imports = [];
  traverseAST(ast, node => {
    // In sass-parse, import nodes have type 'Import' and a `value` string.
    if (node.type === 'Import' && typeof node.value === 'string') {
      imports.push(node.value);
    }
  });
  return imports;
}

/**
 * Resolves an import path relative to the importing file.
 * Handles Sass partials (leading underscore) and file extensions.
 * @param {string} importPath - The raw import string from the file.
 * @param {string} currentFile - The file that contains the import.
 * @returns {string|null} Resolved absolute file path or null if not found.
 */
function resolveImport(importPath, currentFile) {
  const dir = path.dirname(currentFile);
  const extensions = ['.scss', '.sass'];
  const candidates = [];

  // If the import path has an extension, keep it; otherwise try both.
  const hasExt = path.extname(importPath) !== '';
  if (hasExt) {
    candidates.push(importPath);
  } else {
    extensions.forEach(ext => {
      candidates.push(importPath + ext);
    });
  }

  // For each candidate, try adding a leading underscore (partial).
  const resolved = candidates.flatMap(c => {
    const fullPath = path.resolve(dir, c);
    const dirPart = path.dirname(fullPath);
    const basePart = path.basename(fullPath);
    const underscorePath = path.join(dirPart, '_' + basePart);
    return [fullPath, underscorePath];
  });

  // Return the first existing file.
  for (const p of resolved) {
    if (fs.existsSync(p) && fs.statSync(p).isFile()) {
      return p;
    }
  }
  return null;
}

/**
 * Builds a directed graph of Sass imports.
 * @param {string} entryFile - Path to the root Sass file.
 * @param {Object} parser - Sass parser with a `parse(content)` method.
 * @returns {Object} Graph represented as an adjacency list:
 *   { [filePath]: [importedFilePath, ...], ... }
 */
function buildImportGraph(entryFile, parser) {
  const graph = {};          // adjacency list
  const visited = new Set(); // to avoid cycles

  /**
   * Internal recursive function to process a file.
   * @param {string} filePath
   */
  function processFile(filePath) {
    const absPath = path.resolve(filePath);
    if (visited.has(absPath)) return;
    visited.add(absPath);

    const content = fs.readFileSync(absPath, 'utf8');
    const ast = parser.parse(content);

    const imports = extractImports(ast);
    const resolvedImports = [];

    imports.forEach(relPath => {
      const resolved = resolveImport(relPath, absPath);
      if (resolved) {
        resolvedImports.push(resolved);
        processFile(resolved); // recurse
      } else {
        console.warn(`Could not resolve import "${relPath}" in ${absPath}`);
      }
    });

    graph[absPath] = resolvedImports;
  }

  processFile(entryFile);
  return graph;
}

// Export the function for external use
module.exports = {
  buildImportGraph
};
```

