```js
// gfm-extension.js
import { micromark } from 'micromark';
import { createTokenizer } from 'micromark-core';
import { tokenizeCodeFence } from 'micromark-core';
import { tokenizeLink } from 'micromark-core';

// 1️⃣  Add a tokenizer for triple‑backtick code fences (GFM)
function tokenizeGfmCodeFence(effects, ok, nok) {
  return function start(codePoint, silent) {
    // Look for `````` (three backticks)
    if (codePoint !== 0x60 /* ` */) return nok(codePoint);
    let pos = 0;
    let backticks = 0;
    while (backticks < 3) {
      const cp = this.input.charCodeAt(this.at + pos);
      if (cp !== 0x60) return nok(codePoint);
      backticks++;
      pos++;
    }
    // Consume optional language identifier
    let lang = '';
    while (true) {
      const cp = this.input.charCodeAt(this.at + pos);
      if (cp === 0x0A || cp === 0x0D || cp === 0x20 || cp === 0x09) break;
      lang += String.fromCharCode(cp);
      pos++;
    }
    // Skip to end of line
    while (true) {
      const cp = this.input.charCodeAt(this.at + pos);
      if (cp === 0x0A || cp === 0x0D || cp === 0x00) break;
      pos++;
    }
    // Skip the line break
    if (this.input.charCodeAt(this.at + pos) === 0x0D) pos++;
    if (this.input.charCodeAt(this.at + pos) === 0x0A) pos++;

    // Find closing backticks
    const start = this.at + pos;
    let end = start;
    while (true) {
      const cp = this.input.charCodeAt(end);
      if (cp === 0x00) return nok(codePoint);
      if (this.input.slice(end, end + 3) === '```') {
        // Ensure no more backticks on the same line
        const after = end + 3;
        const afterCp = this.input.charCodeAt(after);
        if (afterCp === 0x0A || afterCp === 0x0D || afterCp === 0x00) {
          end = after + 1; // consume line break
          break;
        }
      }
      end++;
    }

    // Emit the token
    if (!silent) {
      effects.enter('codeFence', { lang });
      effects.consume(this.at, this.at + pos);
      effects.enter('codeFenceContent');
      effects.consume(start, end - 3);
      effects.exit('codeFenceContent');
      effects.exit('codeFence');
    }
    this.at = end;
    return ok;
  };
}

// 2️⃣  Add a tokenizer for issue references (e.g., `//123`)
function tokenizeIssueReference(effects, ok, nok) {
  return function start(codePoint, silent) {
    if (codePoint !== 0x2F /* / */) return nok(codePoint);
    const next = this.input.charCodeAt(this.at + 1);
    if (next !== 0x2F) return nok(codePoint); // not a double slash

    // Consume the double slash
    let pos = 2;
    // Consume digits
    let digits = '';
    while (true) {
      const cp = this.input.charCodeAt(this.at + pos);
      if (cp < 0x30 || cp > 0x39) break;
      digits += String.fromCharCode(cp);
      pos++;
    }
    if (digits.length === 0) return nok(codePoint); // no digits after //

    if (!silent) {
      effects.enter('issueReference', { number: digits });
      effects.consume(this.at, this.at + pos);
      effects.exit('issueReference');
    }
    this.at += pos;
    return ok;
  };
}

// 3️⃣  Create the extension
export const gfmExtension = {
  text: {
    // Override the existing code fence rule
    codeFence: tokenizeGfmCodeFence,
    // Add the issue reference rule
    issueReference: tokenizeIssueReference,
  },
  // Optionally, add handlers for the new tokens if you want to transform them
  handlers: {
    codeFence: (node, context, ancestors) => {
      // Example: convert to <pre><code class="language-...">...</code></pre>
      const lang = node.lang || '';
      return `<pre><code class="language-${lang}">${node.children[0].value}</code></pre>`;
    },
    issueReference: (node) => {
      const number = node.number;
      return `<a href="https://github.com/owner/repo/issues/${number}">#${number}</a>`;
    },
  },
};

// 4️⃣  Usage example
// import { micromark } from 'micromark';
// import { gfmExtension } from './gfm-extension.js';
// const html = micromark('# Hello\n\n```js\nconsole.log(\"hi\");\n```\n\nSee //123', { extensions: [gfmExtension] });
// console.log(html);
```

