// aws-resource-manager.js
import {
  LambdaClient,
  CreateFunctionCommand,
  DeleteFunctionCommand,
  ListFunctionsCommand,
} from '@aws-sdk/client-lambda';
import {
  APIGatewayClient,
  CreateRestApiCommand,
  DeleteRestApiCommand,
} from '@aws-sdk/client-apigateway';
import {
  S3Client,
  CreateBucketCommand,
  DeleteBucketCommand,
} from '@aws-sdk/client-s3';
import {
  DynamoDBClient,
  CreateTableCommand,
  DeleteTableCommand,
} from '@aws-sdk/client-dynamodb';
import { fromNodeProviderChain } from '@aws-sdk/credential-provider-node';
import { fromBrowserCredentials } from '@aws-sdk/credential-provider-browser';
import { fromReactNative } from '@aws-sdk/credential-provider-react-native';

export class AWSResourceManager {
  constructor({ region, credentials } = {}) {
    this.region = region || process.env.AWS_REGION || 'us-east-1';
    this.credentials = credentials || this._defaultCredentials();
    this.lambda = new LambdaClient({ region: this.region, credentials: this.credentials });
    this.apiGateway = new APIGatewayClient({ region: this.region, credentials: this.credentials });
    this.s3 = new S3Client({ region: this.region, credentials: this.credentials });
    this.dynamoDB = new DynamoDBClient({ region: this.region, credentials: this.credentials });
  }

  _defaultCredentials() {
    if (typeof window !== 'undefined' && typeof window.document !== 'undefined') {
      return fromBrowserCredentials();
    }
    if (typeof navigator !== 'undefined' && navigator.product === 'ReactNative') {
      return fromReactNative();
    }
    return fromNodeProviderChain();
  }

  // Lambda
  async createLambdaFunction(params) {
    return this.lambda.send(new CreateFunctionCommand(params));
  }
  async deleteLambdaFunction(functionName) {
    return this.lambda.send(new DeleteFunctionCommand({ FunctionName: functionName }));
  }
  async listLambdaFunctions() {
    const { Functions } = await this.lambda.send(new ListFunctionsCommand());
    return Functions;
  }

  // API Gateway
  async createApiGateway(params) {
    return this.apiGateway.send(new CreateRestApiCommand(params));
  }
  async deleteApiGateway(restApiId) {
    return this.apiGateway.send(new DeleteRestApiCommand({ restApiId }));
  }

  // S3
  async createS3Bucket(params) {
    return this.s3.send(new CreateBucketCommand(params));
  }
  async deleteS3Bucket(bucketName) {
    return this.s3.send(new DeleteBucketCommand({ Bucket: bucketName }));
  }

  // DynamoDB
  async createDynamoDBTable(params) {
    return this.dynamoDB.send(new CreateTableCommand(params));
  }
  async deleteDynamoDBTable(tableName) {
    return this.dynamoDB.send(new DeleteTableCommand({ TableName: tableName }));
  }
}
