```js
// main.js
const workerPool = require('worker_pool');
const path = require('path');
const fs = require('fs');
const glob = require('glob');

// Create a pool with 4 workers
const pool = workerPool.pool({
  maxWorkers: 4,
  workerType: 'process',
  workerPath: path.resolve(__dirname, 'worker.js')
});

// Helper to get all files in a directory
function getFiles(dir, pattern = '**/*') {
  return glob.sync(pattern, { cwd: dir, nodir: true });
}

// Run all loaders on a set of files
async function runLoaders() {
  const srcDir = path.resolve(__dirname, 'src');
  const outDir = path.resolve(__dirname, 'dist');

  // Ensure output directory exists
  if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });

  const files = getFiles(srcDir);

  for (const file of files) {
    const ext = path.extname(file).toLowerCase();

    // 1. Load file and copy to output
    await pool.exec('loader1', [srcDir, outDir, file]);

    // 2. If JS, transpile
    if (ext === '.js') {
      await pool.exec('loader2', [outDir, file]);
    }

    // 3. If image, optimize
    if (['.png', '.jpg', '.jpeg', '.gif', '.webp'].includes(ext)) {
      await pool.exec('loader3', [outDir, file]);
    }

    // 4. Analyze size
    await pool.exec('loader4', [outDir, file]);
  }

  // Close the pool
  pool.terminate();
}

runLoaders().catch(err => console.error(err));
