// worker.js
const fs = require('fs');
const path = require('path');
const es6 = require('@babel/core');
const sharp = require('sharp');
const workerPool = require('worker_pool');

workerPool.worker({
  loader1: async (srcDir, outDir, file) => {
    const srcPath = path.join(srcDir, file);
    const outPath = path.join(outDir, file);
    const data = await fs.promises.readFile(srcPath);
    await fs.promises.mkdir(path.dirname(outPath), { recursive: true });
    await fs.promises.writeFile(outPath, data);
  },

  loader2: async (outDir, file) => {
    const filePath = path.join(outDir, file);
    const code = await fs.promises.readFile(filePath, 'utf8');
    const { code: transpiled } = await es6.transformAsync(code, {
      presets: ['@babel/preset-env'],
      sourceType: 'module'
    });
    await fs.promises.writeFile(filePath, transpiled, 'utf8');
  },

  loader3: async (outDir, file) => {
    const filePath = path.join(outDir, file);
    const ext = path.extname(file).toLowerCase();
    const image = sharp(filePath);
    if (ext === '.png') {
      await image.png({ quality: 80 }).toFile(filePath);
    } else if (['.jpg', '.jpeg'].includes(ext)) {
      await image.jpeg({ quality: 80 }).toFile(filePath);
    } else if (ext === '.gif') {
      await image.gif({ quality: 80 }).toFile(filePath);
    } else if (ext === '.webp') {
      await image.webp({ quality: 80 }).toFile(filePath);
    }
  },

  loader4: async (outDir, file) => {
    const filePath = path.join(outDir, file);
    const stats = await fs.promises.stat(filePath);
    console.log(`Size of ${file}: ${stats.size} bytes`);
  }
});
