```js
// main.js
const { Worker } = require('worker_threads');
const path = require('path');
const os = require('os');

class WorkerPool {
  constructor(workerScript, size = os.cpus().length) {
    this.size = size;
    this.workers = [];
    this.idleWorkers = [];
    this.taskQueue = [];

    for (let i = 0; i < size; i++) {
      const worker = new Worker(workerScript);
      worker.on('message', (msg) => this._handleResult(worker, msg));
      worker.on('error', (err) => console.error('Worker error:', err));
      worker.on('exit', (code) => {
        if (code !== 0) console.error(`Worker stopped with exit code ${code}`);
      });
      this.workers.push(worker);
      this.idleWorkers.push(worker);
    }
  }

  _handleResult(worker, result) {
    const { resolve, reject } = worker.currentTask;
    if (result.error) reject(result.error);
    else resolve(result.data);
    worker.currentTask = null;
    this.idleWorkers.push(worker);
    this._processQueue();
  }

  _processQueue() {
    if (!this.taskQueue.length || !this.idleWorkers.length) return;
    const { task, resolve, reject } = this.taskQueue.shift();
    const worker = this.idleWorkers.shift();
    worker.currentTask = { resolve, reject };
    worker.postMessage(task);
  }

  runTask(task) {
    return new Promise((resolve, reject) => {
      this.taskQueue.push({ task, resolve, reject });
      this._processQueue();
    });
  }

  close() {
    for (const worker of this.workers) worker.terminate();
  }
}

// Example usage
(async () => {
  const pool = new WorkerPool(path.resolve(__dirname, 'worker.js'), 4);

  // loader1: copy file from src to dest
  await pool.runTask({
    type: 'loader1',
    src: './src/file.txt',
    dest: './dist/file.txt',
  });

  // loader2: transpile ES6 to ES5 (stubbed)
  const transpiled = await pool.runTask({
    type: 'loader2',
    code: 'const x = () => console.log("ES6");',
  });
  console.log('Transpiled code:', transpiled);

  // loader3: optimize image (stubbed)
  await pool.runTask({
    type: 'loader3',
    src: './images/photo.png',
    dest: './dist/photo.png',
  });

  // loader4: analyze file size
  const sizeInfo = await pool.runTask({
    type: 'loader4',
    file: './dist/file.txt',
  });
  console.log('File size:', sizeInfo);

  pool.close();
})();
