```js
// pluginHelper.js
const fp = require('fastify-plugin');
const fastifyAuth = require('fastify-auth');
const fastifyCacheableRequest = require('fastify-cacheable-request');
const fastifyCache = require('fastify-caching');

/**
 * Creates a Fastify plugin that registers optional authentication,
 * caching, and any other custom functionalities.
 *
 * @param {Object} options
 * @param {Object} [options.auth] - Options for fastify-auth
 * @param {Object} [options.cache] - Options for fastify-caching
 * @param {Array<Function>} [options.custom] - Array of custom plugin functions to register
 * @returns {Function} Fastify plugin
 */
function createPluginHelper({ auth, cache, custom = [] } = {}) {
  return fp(async function (fastify, _opts) {
    // Register authentication if provided
    if (auth) {
      fastify.register(fastifyAuth, auth);
    }

    // Register caching if provided
    if (cache) {
      fastify.register(fastifyCache, cache);
      fastify.register(fastifyCacheableRequest, cache);
    }

    // Register any custom plugins
    for (const plugin of custom) {
      fastify.register(plugin);
    }

    // Example: expose a helper method on the Fastify instance
    fastify.decorate('helper', {
      greet(name) {
        return `Hello, ${name}!`;
      },
    });
  });
}

module.exports = createPluginHelper;
