```javascript
// eslint-plugin-react-native-lint/rules/component-naming.js
/**
 * @fileoverview Enforce PascalCase component names for React Native components.
 */
"use strict";

module.exports = {
  meta: {
    type: "suggestion",
    docs: {
      description: "enforce PascalCase component names",
      category: "Stylistic Issues",
      recommended: false,
    },
    schema: [
      {
        type: "object",
        properties: {
          allowAnonymous: { type: "boolean" },
        },
        additionalProperties: false,
      },
    ],
    messages: {
      notPascalCase: "Component name '{{name}}' should be in PascalCase.",
    },
  },

  create(context) {
    const options = context.options[0] || {};
    const allowAnonymous = options.allowAnonymous || false;

    function checkName(name, node) {
      if (!name) return;
      const pascalCase = /^[A-Z][A-Za-z0-9]*$/;
      if (!pascalCase.test(name)) {
        context.report({
          node,
          messageId: "notPascalCase",
          data: { name },
        });
      }
    }

    return {
      FunctionDeclaration(node) {
        if (node.id && node.id.name) {
          checkName(node.id.name, node);
        }
      },
      ClassDeclaration(node) {
        if (node.id && node.id.name) {
          checkName(node.id.name, node);
        }
      },
      ArrowFunctionExpression(node) {
        if (!allowAnonymous && node.parent.type === "VariableDeclarator") {
          const name = node.parent.id.name;
          checkName(name, node.parent);
        }
      },
    };
  },
};
