// eslint-plugin-react-native-lint/rules/style-consistency.js
/**
 * @fileoverview Enforce consistent style usage: prefer StyleSheet.create over inline styles.
 */
"use strict";

module.exports = {
  meta: {
    type: "suggestion",
    docs: {
      description: "enforce consistent style usage",
      category: "Stylistic Issues",
      recommended: false,
    },
    schema: [
      {
        type: "object",
        properties: {
          allowInline: { type: "boolean" },
        },
        additionalProperties: false,
      },
    ],
    messages: {
      inlineStyle: "Avoid inline styles; use StyleSheet.create instead.",
    },
  },

  create(context) {
    const options = context.options[0] || {};
    const allowInline = options.allowInline || false;

    return {
      JSXAttribute(node) {
        if (node.name.name !== "style") return;
        const value = node.value;
        if (!value) return;

        // Inline style object
        if (value.type === "JSXExpressionContainer" &&
            value.expression.type === "ObjectExpression") {
          if (!allowInline) {
            context.report({
              node: value.expression,
              messageId: "inlineStyle",
            });
          }
        }
      },
    };
  },
};
