```javascript
// eslint-plugin-react-native-lint/rules/prop-usage.js
/**
 * @fileoverview Warn about unused props in component definitions.
 */
"use strict";

module.exports = {
  meta: {
    type: "problem",
    docs: {
      description: "warn about unused props",
      category: "Possible Errors",
      recommended: false,
    },
    schema: [],
    messages: {
      unusedProp: "Prop '{{propName}}' is defined but never used.",
    },
  },

  create(context) {
    const usedProps = new Set();

    function collectUsedProps(node) {
      if (!node) return;
      if (node.type === "Identifier" && node.name !== "props") {
        usedProps.add(node.name);
      }
      for (const key in node) {
        const child = node[key];
        if (Array.isArray(child)) {
          child.forEach(collectUsedProps);
        } else if (child && typeof child.type === "string") {
          collectUsedProps(child);
        }
      }
    }

    return {
      FunctionDeclaration(node) {
        const params = node.params;
        if (!params.length) return;
        const propsParam = params[0];
        if (propsParam.type !== "Identifier") return;
        const propsName = propsParam.name;

        // Reset used props for this component
        usedProps.clear();

        // Find all Identifier nodes that reference props
        context.getSourceCode().traverse(node.body, {
          Identifier(innerNode) {
            if (innerNode.name === propsName) {
              const parent = innerNode.parent;
              if (parent && parent.type === "MemberExpression" &&
                  parent.object === innerNode) {
                usedProps.add(parent.property.name);
              }
            }
          },
        });

        // Find propTypes or TypeScript type annotations
        let definedProps = new Set();
        if (node.parent && node.parent.type === "VariableDeclarator") {
          // Check for propTypes assignment
          const parent = node.parent.parent.parent;
          if (parent && parent.type === "ExpressionStatement") {
            const expr = parent.expression;
            if (expr.type === "AssignmentExpression" &&
                expr.left.type === "MemberExpression" &&
                expr.left.property.name === "propTypes") {
              const right = expr.right;
              if (right.type === "ObjectExpression") {
                right.properties.forEach((prop) => {
                  if (prop.key && prop.key.type === "Identifier") {
                    definedProps.add(prop.key.name);
                  }
                });
              }
            }
          }
        }

        // Report unused props
        definedProps.forEach((propName) => {
          if (!usedProps.has(propName)) {
            context.report({
              node,
              messageId: "unusedProp",
              data: { propName },
            });
          }
        });
      },
    };
  },
};
```

