// Excel Workbook Manager example (Node.js)

const { WorkbookManager } = require('excel-workbook-manager');
const path = require('path');

// Create a new workbook manager instance
const wbManager = new WorkbookManager();

/**
 * Read an XLSX file and return the workbook object.
 * @param {string} filePath - Path to the XLSX file.
 * @returns {Promise<Object>} - Workbook data.
 */
async function readXlsx(filePath) {
  const absolutePath = path.resolve(filePath);
  const workbook = await wbManager.readXlsx(absolutePath);
  return workbook;
}

/**
 * Read a CSV file and return the workbook object.
 * @param {string} filePath - Path to the CSV file.
 * @returns {Promise<Object>} - Workbook data.
 */
async function readCsv(filePath) {
  const absolutePath = path.resolve(filePath);
  const workbook = await wbManager.readCsv(absolutePath);
  return workbook;
}

/**
 * Write a workbook object to an XLSX file.
 * @param {Object} workbook - Workbook data.
 * @param {string} filePath - Destination path for the XLSX file.
 * @returns {Promise<void>}
 */
async function writeXlsx(workbook, filePath) {
  const absolutePath = path.resolve(filePath);
  await wbManager.writeXlsx(workbook, absolutePath);
}

/**
 * Write a workbook object to a CSV file.
 * @param {Object} workbook - Workbook data.
 * @param {string} filePath - Destination path for the CSV file.
 * @returns {Promise<void>}
 */
async function writeCsv(workbook, filePath) {
  const absolutePath = path.resolve(filePath);
  await wbManager.writeCsv(workbook, absolutePath);
}

/**
 * Example: Load an XLSX, modify data, and save as CSV.
 */
async function example() {
  // Load XLSX
  const workbook = await readXlsx('./input.xlsx');

  // Modify data: add a new column to the first sheet
  const sheet = workbook.sheets[0];
  sheet.columns.push({ header: 'New Column', key: 'newColumn', width: 15 });
  sheet.data.forEach(row => {
    row.newColumn = 'Sample Data';
  });

  // Save as CSV
  await writeCsv(workbook, './output.csv');
}

