// Dependencies
import { parse, print, visit, Kind } from 'graphql';
import { buildASTSchema, GraphQLSchema, GraphQLObjectType, GraphQLFieldConfigMap } from 'graphql';
import { jsonSchemaToGraphQL } from 'graphql-jsonschema';
import gql from 'graphql-tag';

// Create a GraphQL schema from a JSON Schema
export function createSchemaFromJSON(jsonSchema) {
  const sdl = jsonSchemaToGraphQL(jsonSchema);
  const ast = parse(sdl);
  return buildASTSchema(ast);
}

// Utility: add a field to an existing type
export function addField(schema, typeName, fieldName, fieldConfig) {
  const type = schema.getType(typeName);
  if (!type || !(type instanceof GraphQLObjectType)) {
    throw new Error(`Type ${typeName} not found or not an object type`);
  }
  const fields = type.getFields();
  if (fields[fieldName]) {
    throw new Error(`Field ${fieldName} already exists on ${typeName}`);
  }
  const newFields = { ...fields, [fieldName]: fieldConfig };
  const newType = new GraphQLObjectType({
    name: typeName,
    fields: newFields,
    interfaces: type.getInterfaces(),
    description: type.description,
    astNode: type.astNode,
    extensionASTNodes: type.extensionASTNodes,
  });
  const newSchema = new GraphQLSchema({
    ...schema.toConfig(),
    types: schema.getTypeMap(),
    query: schema.getQueryType(),
    mutation: schema.getMutationType(),
    subscription: schema.getSubscriptionType(),
  });
  newSchema._typeMap[typeName] = newType;
  return newSchema;
}

// Utility: remove a field from an existing type
export function removeField(schema, typeName, fieldName) {
  const type = schema.getType(typeName);
  if (!type || !(type instanceof GraphQLObjectType)) {
    throw new Error(`Type ${typeName} not found or not an object type`);
  }
  const fields = type.getFields();
  if (!fields[fieldName]) {
    throw new Error(`Field ${fieldName} does not exist on ${typeName}`);
  }
  const newFields = { ...fields };
  delete newFields[fieldName];
  const newType = new GraphQLObjectType({
    name: typeName,
    fields: newFields,
    interfaces: type.getInterfaces(),
    description: type.description,
    astNode: type.astNode,
    extensionASTNodes: type.extensionASTNodes,
  });
  const newSchema = new GraphQLSchema({
    ...schema.toConfig(),
    types: schema.getTypeMap(),
    query: schema.getQueryType(),
    mutation: schema.getMutationType(),
    subscription: schema.getSubscriptionType(),
  });
  newSchema._typeMap[typeName] = newType;
  return newSchema;
}

// Utility: modify a field's config
export function modifyField(schema, typeName, fieldName, newConfig) {
  const type = schema.getType(typeName);
  if (!type || !(type instanceof GraphQLObjectType)) {
    throw new Error(`Type ${typeName} not found or not an object type`);
  }
  const fields = type.getFields();
  if (!fields[fieldName]) {
    throw new Error(`Field ${fieldName} does not exist on ${typeName}`);
  }
  const newFields = { ...fields, [fieldName]: newConfig };
  const newType = new GraphQLObjectType({
    name: typeName,
    fields: newFields,
    interfaces: type.getInterfaces(),
    description: type.description,
    astNode: type.astNode,
    extensionASTNodes: type.extensionASTNodes,
  });
  const newSchema = new GraphQLSchema({
    ...schema.toConfig(),
    types: schema.getTypeMap(),
    query: schema.getQueryType(),
    mutation: schema.getMutationType(),
