```js
// Dependencies: npm install sass-js
const fs = require('fs').promises;
const path = require('path');
const sass = require('sass-js');

/**
 * Recursively find all Sass dependencies of a given file.
 * @param {string} entryPath - Path to the entry Sass file.
 * @returns {Promise<string[]>} - Array of absolute paths to imported Sass files.
 */
async function findSassDependencies(entryPath) {
  const visited = new Set();
  const imports = new Set();

  async function processFile(filePath) {
    const absPath = path.resolve(filePath);
    if (visited.has(absPath)) return;
    visited.add(absPath);

    let content;
    try {
      content = await fs.readFile(absPath, 'utf8');
    } catch (err) {
      console.warn(`Could not read ${absPath}: ${err.message}`);
      return;
    }

    // Use sass-js to compile (just to trigger any Sass-specific preprocessing)
    // The compiled CSS is not used; we only need the original content.
    try {
      sass.compile(content, { syntax: path.extname(absPath) === '.sass' ? 'indented' : 'scss' });
    } catch (e) {
      // ignore compile errors – we only need the source
    }

    // Regex to capture @import statements
    const importRegex = /@import\s+(['"])([^'"]+)\1\s*;/g;
    let match;
    while ((match = importRegex.exec(content)) !== null) {
      const importPath = match[2].trim();

      // Skip CSS imports
      if (importPath.endsWith('.css')) continue;

      // Resolve relative to current file
      const dir = path.dirname(absPath);
      let resolved = path.resolve(dir, importPath);

      // Try common Sass import resolutions
      const candidates = [
        resolved,
        `${resolved}.scss`,
        `${resolved}.sass`,
        `_${resolved}.scss`,
        `_${resolved}.sass`,
      ];

      let found = null;
      for (const cand of candidates) {
        try {
          await fs.access(cand);
          found = cand;
          break;
        } catch (_) {}
      }

      if (!found) {
        console.warn(`Could not resolve import "${importPath}" in ${absPath}`);
        continue;
      }

      imports.add(found);
      await processFile(found);
    }
  }

  await processFile(entryPath);
  return Array.from(imports);
}

// Example usage:
// (async () => {
//   const deps = await findSassDependencies('./styles/main.scss');
//   console.log(deps);
// })();
```

