```javascript
// editor-commands.js
import { Schema, DOMParser, DOMSerializer } from "prosemirror-model";
import { EditorState, Plugin, TextSelection } from "prosemirror-state";
import { keymap } from "prosemirror-keymap";
import { baseKeymap, toggleMark, setBlockType, wrapInList, setTextSelection, deleteSelection, replaceSelection, chainCommands } from "prosemirror-commands";
import { history, undo, redo } from "prosemirror-history";
import { schema as basicSchema } from "prosemirror-schema-basic";
import { schema as listSchema } from "prosemirror-schema-list";
import { schema as linkSchema } from "prosemirror-schema-link";
import { schema as imageSchema } from "prosemirror-schema-image";

// Extend the basic schema with underline, color, link, image, and list support
const nodes = basicSchema.spec.nodes
  .append(listSchema.spec.nodes)
  .append(imageSchema.spec.nodes);

const marks = basicSchema.spec.marks
  .append(linkSchema.spec.marks)
  .addToEnd("underline", {
    attrs: {},
    inclusive: false,
    parseDOM: [{ tag: "u" }],
    toDOM() { return ["u", 0]; }
  })
  .addToEnd("color", {
    attrs: { color: {} },
    inclusive: false,
    parseDOM: [{
      style: "color",
      getAttrs: value => ({ color: value })
    }],
    toDOM(mark) { return ["span", { style: `color:${mark.attrs.color}` }, 0]; }
  });

const mySchema = new Schema({ nodes, marks });

// Command: toggle bold
export const toggleBold = toggleMark(mySchema.marks.strong);

// Command: toggle italic
export const toggleItalic = toggleMark(mySchema.marks.em);

// Command: toggle underline
export const toggleUnderline = toggleMark(mySchema.marks.underline);

// Command: set text color
export function setTextColor(color) {
  return function(state, dispatch) {
    const { from, to } = state.selection;
    if (from === to) return false; // no selection
    const mark = mySchema.marks.color.create({ color });
    if (dispatch) {
      dispatch(state.tr.addMark(from, to, mark));
    }
    return true;
  };
}

// Command: insert link
export function insertLink(href, title = "") {
  return function(state, dispatch) {
    const { from, to } = state.selection;
    if (from === to) return false; // no selection
    const mark = mySchema.marks.link.create({ href, title });
    if (dispatch) {
      dispatch(state.tr.addMark(from, to, mark));
    }
    return true;
  };
}

// Command: create bullet list
export const createBulletList = wrapInList(mySchema.nodes.bullet_list);

// Command: create ordered list
export const createOrderedList = wrapInList(mySchema.nodes.ordered_list);

// Command: insert image
export function insertImage(src, alt = "", title = "") {
  return function(state, dispatch) {
    const node = mySchema.nodes.image.create({ src, alt, title });
    if (dispatch) {
      const tr = state.tr.replaceSelectionWith(node).scrollIntoView();
      dispatch(tr);
    }
    return true;
  };
}

// Command: remove all formatting marks from selection
export function removeFormatting() {
  return function(state, dispatch) {
    const { from, to } = state.selection;
    if (from === to) return false;
    const tr = state.tr;
    mySchema.marks.forEach(mark => {
      tr.removeMark(from, to, mark);
    });
    if (dispatch) dispatch(tr);
    return true;
  };
}

// Command: undo
export const undoCommand = undo;

// Command: redo
export const redoCommand = redo;

// Example usage: create an editor view
import { EditorView } from "prosemirror-view";

const state = EditorState.create({
  doc: DOMParser.fromSchema(mySchema).parse(document.createElement("div")),
  plugins: [
    history(),
    keymap({
      "Mod-b": toggleBold,
      "Mod-i": toggleItalic,
      "Mod-u": toggleUnderline,
      "Mod-Shift-1": setTextColor("red"),
      "Mod-Shift-2": setTextColor("blue"),
      "Mod-k": chainCommands(insertLink("https://example.com"), setTextSelection),
      "Mod-Shift-8": createBulletList,
      "Mod-Shift-9": createOrderedList,
      "Mod-Shift-0": insertImage("https://example.com/image.png"),
      "Mod-Shift-Backspace": removeFormatting,
      "Mod-z": undoCommand,
      "Mod-y": redoCommand
    }),
    keymap(baseKeymap)
  ]
});

const view = new EditorView(document.querySelector("#editor"), { state });
```

