```js
// main.js
import {EditorView, basicSetup} from "@codemirror/basic-setup";
import {javascript} from "@codemirror/lang-javascript";
import {autocomplete, CompletionContext, CompletionResult} from "@codemirror/autocomplete";
import {keymap} from "@codemirror/view";
import {lsp} from "@codemirror/language-server"; // optional LSP integration

// ---------- Custom completion source that queries an external API ----------
async function externalCompletionSource(context) {
  const word = context.matchBefore(/\w*/);
  if (!word) return null;

  // Example: fetch completions from a hypothetical API
  const response = await fetch(
    `https://api.example.com/completions?q=${encodeURIComponent(word.text)}`
  );
  if (!response.ok) return null;

  const data = await response.json(); // expects { suggestions: [{label, type, detail}] }
  const completions = data.suggestions.map(item => ({
    label: item.label,
    type: item.type,
    detail: item.detail,
    apply: item.apply ?? item.label
  }));

  return {
    from: word.from,
    options: completions,
    validFor: /\w*/
  };
}

// ---------- Optional: LSP integration (requires a running language server) ----------
const lspExtension = lsp({
  // The LSP client configuration
  // For example, using the JavaScript language server
  server: {
    // Path to the language server executable
    command: "node",
    args: ["path/to/javascript-language-server.js"],
    // Optional: specify the language server's root directory
    rootUri: "file://"
  },
  // The language to use for the editor
  language: "javascript"
});

// ---------- Editor setup ----------
const editor = new EditorView({
  state: EditorState.create({
    doc: "// Start typing...",
    extensions: [
      basicSetup,
      javascript(),
      autocomplete({
        override: [externalCompletionSource] // add custom source
      }),
      keymap.of([{
        key: "Ctrl-Space",
        run: autocomplete.startCompletion
      }]),
      lspExtension // comment out if LSP not needed
    ]
  }),
  parent: document.getElementById("editor")
});
