// rollup-plugin-native-transform.js
import { createFilter } from '@rollup/pluginutils';
import nativeTransform from 'native-transform'; // compiled native addon

export default function nativeTransformPlugin(options = {}) {
  const filter = createFilter(options.include, options.exclude);

  return {
    name: 'native-transform',
    transform(code, id) {
      if (!filter(id)) return null;

      // Use the native binding to transform the code
      const transformed = nativeTransform.transform(code, id);

      return {
        code: transformed,
        map: null // or provide a source map if the native binding supports it
      };
    }
  };
}
