```js
// build.js
// Run with: node build.js

const path = require('path');
const fs = require('fs');
const { analyze } = require('ts-analysis');
const { generateDocs } = require('ts-doc');
const { rollup } = require('rollup');
const dts = require('rollup-plugin-dts');

// ---------- 1. Analyze exported API ----------
async function analyzeAPI() {
  const tsconfigPath = path.resolve(__dirname, 'tsconfig.json');
  const { program } = analyze(tsconfigPath);
  const exports = program.getSourceFiles()
    .filter(sf => !sf.isDeclarationFile)
    .flatMap(sf => sf.getExportedDeclarations())
    .map(([name, decls]) => ({ name, decls }));

  // Simple review: list exported symbols
  const review = exports.map(e => e.name).join('\n');
  fs.writeFileSync('api-review.txt', review);
  console.log('API review written to api-review.txt');
  return exports;
}

// ---------- 2. Generate documentation ----------
async function generateDocumentation() {
  const docsDir = path.resolve(__dirname, 'docs');
  if (!fs.existsSync(docsDir)) fs.mkdirSync(docsDir);
  await generateDocs({
    tsconfig: 'tsconfig.json',
    outDir: docsDir,
    include: ['src/**/*.ts'],
  });
  console.log('Documentation generated in docs/');
}

// ---------- 3. Rollup JS bundle ----------
async function bundleJS() {
  const bundle = await rollup({
    input: 'src/index.ts',
    plugins: [],
  });
  await bundle.write({
    file: 'dist/bundle.js',
    format: 'cjs',
    sourcemap: true,
  });
  console.log('JS bundle written to dist/bundle.js');
}

// ---------- 4. Rollup .d.ts bundle ----------
async function bundleDTS() {
  const bundle = await rollup({
    input: 'src/index.ts',
    plugins: [dts()],
  });
  await bundle.write({
    file: 'dist/index.d.ts',
    format: 'es',
  });
  console.log('DTS bundle written to dist/index.d.ts');
}

// ---------- Main ----------
(async () => {
  await analyzeAPI();
  await generateDocumentation();
  await bundleJS();
  await bundleDTS();
})();
