// Load environment variables
require('dotenv').config();

// Import the SFDX client library
const SfdxClient = require('sfdx-client');

/**
 * Initializes an SFDX client, authenticates, and returns the client
 * along with organization information.
 *
 * @returns {Promise<{client: SfdxClient, orgInfo: object}>}
 */
async function initSfdxClient() {
  const {
    SF_USERNAME,
    SF_PASSWORD,
    SF_SECURITY_TOKEN,
    SF_LOGIN_URL = 'https://login.salesforce.com',
  } = process.env;

  if (!SF_USERNAME || !SF_PASSWORD || !SF_SECURITY_TOKEN) {
    throw new Error('Missing Salesforce credentials in environment variables.');
  }

  // Create the client instance
  const client = new SfdxClient({
    loginUrl: SF_LOGIN_URL,
  });

  // Authenticate with Salesforce
  await client.authenticate({
    username: SF_USERNAME,
    password: SF_PASSWORD,
    securityToken: SF_SECURITY_TOKEN,
  });

  // Retrieve organization information
  const orgInfo = await client.getOrgInfo();

  return { client, orgInfo };
}

module.exports = { initSfdxClient };
