```javascript
// rpc-server.js
const express = require('express');
const bodyParser = require('body-parser');
const atob = require('atob'); // npm install atob

const app = express();
app.use(bodyParser.json());

// ---------- Basic Auth Middleware ----------
const USERS = { 'alice': 'wonderland', 'bob': 'builder' }; // username:password

function basicAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Basic ')) {
    res.set('WWW-Authenticate', 'Basic realm="RPC"');
    return res.status(401).json({ error: 'Missing or invalid Authorization header' });
  }

  const base64Credentials = authHeader.split(' ')[1];
  const credentials = atob(base64Credentials).split(':');
  const [username, password] = credentials;

  if (USERS[username] && USERS[username] === password) {
    req.user = username;
    return next();
  }

  res.set('WWW-Authenticate', 'Basic realm="RPC"');
  return res.status(401).json({ error: 'Invalid credentials' });
}

app.use(basicAuth);

// ---------- RPC Procedure Registry ----------
const procedures = {
  add: (a, b) => a + b,
  subtract: (a, b) => a - b,
  // Example async procedure
  async multiply(a, b) {
    return new Promise((resolve) => setTimeout(() => resolve(a * b), 100));
  },
  // Example procedure that throws an error
  divide(a, b) {
    if (b === 0) throw new Error('Division by zero');
    return a / b;
  },
};

// ---------- RPC Endpoint ----------
app.post('/rpc', async (req, res) => {
  const { method, params } = req.body;

  if (!method || !Array.isArray(params)) {
    return res.status(400).json({ error: 'Invalid request format' });
  }

  const proc = procedures[method];
  if (!proc) {
    return res.status(404).json({ error: `Method "${method}" not found` });
  }

  try {
    const result = await proc(...params);
    res.json({ result });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ---------- Start Server ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`RPC server listening on port ${PORT}`);
});
