```js
const http = require('http');

class RPCServer {
  constructor({ host = '0.0.0.0', port = 3000, auth = null }) {
    this.host = host;
    this.port = port;
    this.methods = new Map();
    this.auth = auth; // { username, password }
    this.server = http.createServer(this.handleRequest.bind(this));
  }

  registerMethod(name, fn) {
    if (typeof fn !== 'function') throw new Error('Method must be a function');
    this.methods.set(name, fn);
  }

  handleRequest(req, res) {
    // Basic auth
    if (this.auth) {
      const authHeader = req.headers['authorization'];
      if (!authHeader || !authHeader.startsWith('Basic ')) {
        res.writeHead(401, { 'WWW-Authenticate': 'Basic realm="RPC"' });
        return res.end('Authentication required');
      }
      const base64Credentials = authHeader.split(' ')[1];
      const credentials = Buffer.from(base64Credentials, 'base64').toString('utf8');
      const [username, password] = credentials.split(':');
      if (username !== this.auth.username || password !== this.auth.password) {
        res.writeHead(403);
        return res.end('Forbidden');
      }
    }

    if (req.method !== 'POST') {
      res.writeHead(405, { 'Allow': 'POST' });
      return res.end('Method Not Allowed');
    }

    let body = '';
    req.on('data', chunk => { body += chunk; });
    req.on('end', () => {
      let payload;
      try {
        payload = JSON.parse(body);
      } catch (e) {
        res.writeHead(400);
        return res.end('Invalid JSON');
      }

      const { method, params } = payload;
      if (!method || !this.methods.has(method)) {
        res.writeHead(404);
        return res.end('Method not found');
      }

      const fn = this.methods.get(method);
      Promise.resolve()
        .then(() => fn(...params))
        .then(result => {
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ result }));
        })
        .catch(err => {
          res.writeHead(500, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: err.message }));
        });
    });
  }

  start() {
    this.server.listen(this.port, this.host, () => {
      console.log(`RPC server listening on ${this.host}:${this.port}`);
    });
  }

  stop() {
    this.server.close();
  }
}

// Example usage
const rpc = new RPCServer({
  host: '127.0.0.1',
  port: 4000,
  auth: { username: 'user', password: 'pass' }
});

rpc.registerMethod('add', (a, b) => a + b);
rpc.registerMethod('multiply', (a, b) => a * b);
rpc.registerMethod('echo', msg => msg);

rpc.start();
```

