// RichTextField.js
import React, { useEffect, useState } from 'react';
import { useExtension } from '@contentful/react-apps-toolkit';
import { RichTextEditor } from '@contentful/rich-text-editor';
import { documentToReactComponents } from '@contentful/rich-text-react-renderer';

/**
 * Editor component that syncs with a Contentful rich‑text field.
 */
export const RichTextField = () => {
  const { field } = useExtension();
  const [value, setValue] = useState(
    field.getValue() || { nodeType: 'document', content: [] }
  );

  useEffect(() => {
    const onFieldChange = () => {
      setValue(field.getValue() || { nodeType: 'document', content: [] });
    };
    field.onValueChanged(onFieldChange);
    return () => field.offValueChanged(onFieldChange);
  }, [field]);

  const handleChange = (newValue) => {
    setValue(newValue);
    field.setValue(newValue);
  };

  return (
    <RichTextEditor
      value={value}
      onChange={handleChange}
    />
  );
};

/**
 * Renderer component that turns a Contentful rich‑text document into React.
 */
export const RichTextRenderer = ({ document }) => (
  <div>{documentToReactComponents(document)}</div>
);
```

