```js
// Requires the sqldb library (npm install sqldb)
const sqldb = require('sqldb');

/**
 * Executes a SQL query and returns a summary.
 *
 * @param {string} sql      The SQL query to execute.
 * @param {Array}  [params] Optional parameters for the query.
 * @returns {Promise<Object>} Summary of the execution.
 */
async function executeQuery(sql, params = []) {
  // Create a connection to the MySQL database
  const conn = sqldb.createConnection({
    host:     'localhost',
    user:     'root',
    password: 'your_password',
    database: 'your_database',
  });

  // Measure execution time
  const start = Date.now();

  // Execute the query (sqldb returns a promise if no callback is supplied)
  let result;
  try {
    result = await conn.query(sql, params);
  } catch (err) {
    conn.end();
    throw err;
  }

  const end = Date.now();
  const execTimeMs = end - start;

  // Determine affected rows by query type
  const firstWord = sql.trim().split(/\s+/)[0].toUpperCase();
  let inserted = 0, updated = 0, deleted = 0, affected = 0;

  if (result && typeof result.affectedRows === 'number') {
    affected = result.affectedRows;
    if (firstWord === 'INSERT') inserted = result.affectedRows;
    if (firstWord === 'UPDATE') updated = result.affectedRows;
    if (firstWord === 'DELETE') deleted = result.affectedRows;
  }

  // Close the connection
  conn.end();

  return {
    affectedRows: affected,
    inserted,
    updated,
    deleted,
    executionTimeMs: execTimeMs,
  };
}

