function splitIndices(df, trainFrac = 0.6, valFrac = 0.2, testFrac = 0.2, randomState = null) {
  // Ensure fractions sum to 1
  const total = trainFrac + valFrac + testFrac;
  if (Math.abs(total - 1.0) > 1e-6) {
    throw new Error('trainFrac + valFrac + testFrac must equal 1');
  }

  // Get all indices
  const allIndices = df.index.tolist();

  // First split: train vs remaining (val + test)
  const [trainIdx, remainingIdx] = train_test_split(
    allIndices,
    { train_size: trainFrac, random_state: randomState }
  );

  // Second split: validation vs test
  const valTestFrac = valFrac / (valFrac + testFrac); // proportion of remaining that goes to validation
  const [valIdx, testIdx] = train_test_split(
    remainingIdx,
    { test_size: 1 - valTestFrac, random_state: randomState }
  );

  return { trainIdx, valIdx, testIdx };
}

// Example usage:
// const { trainIdx, valIdx, testIdx } = splitIndices(df, 0.7, 0.15, 0.15, 42);
// const trainSet = df.loc[trainIdx];
// const valSet   = df.loc[valIdx];
// const testSet  = df.loc[testIdx];
```

