```javascript
/**
 * Split an array of indices into train, validation, and test sets.
 *
 * @param {Array} indices - Array of indices to split.
 * @param {number} trainRatio - Proportion of data for training (0 < trainRatio < 1).
 * @param {number} valRatio - Proportion of data for validation (0 < valRatio < 1).
 * @returns {Object} { train: Array, val: Array, test: Array }
 */
function splitIndices(indices, trainRatio, valRatio) {
  if (trainRatio + valRatio >= 1) {
    throw new Error('trainRatio + valRatio must be less than 1');
  }

  // Fisher–Yates shuffle
  const shuffled = indices.slice();
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }

  const total = shuffled.length;
  const trainEnd = Math.floor(total * trainRatio);
  const valEnd = trainEnd + Math.floor(total * valRatio);

  const train = shuffled.slice(0, trainEnd);
  const val = shuffled.slice(trainEnd, valEnd);
  const test = shuffled.slice(valEnd);

  return { train, val, test };
}

// Example usage:
const allIndices = Array.from({ length: 1000 }, (_, i) => i);
const { train, val, test } = splitIndices(allIndices, 0.7, 0.15);
console.log('Train size:', train.length);
console.log('Validation size:', val.length);
console.log('Test size:', test.length);
```

