```javascript
// app/components/example-component.js
import Component from '@glimmer/component';
import { action } from '@ember/object';
import { scheduleOnce, next } from '@ember/runloop';

export default class ExampleComponent extends Component {
  // This flag will be set after the DOM has been updated
  domUpdated = false;

  // Called when the component is inserted into the DOM
  @action
  didInsertElement() {
    // 1️⃣ Schedule a task to run after the current run‑loop finishes
    //    (i.e. after all DOM updates for this insertion are complete)
    scheduleOnce('afterRender', this, this.afterRender);

    // 2️⃣ Schedule a task to run on the next run‑loop cycle
    //    (useful if you need to wait for a subsequent event)
    next(this, this.nextCycle);
  }

  // Runs in the 'afterRender' queue of the current run‑loop
  afterRender() {
    // At this point the component's template has been rendered
    // and the DOM nodes are available.
    this.domUpdated = true;
    console.log('DOM updated in current run‑loop');
  }

  // Runs in the next run‑loop cycle
  nextCycle() {
    console.log('This runs in the next run‑loop cycle');
  }

  // Example of deferring a heavy computation until after the UI is responsive
  @action
  heavyTask() {
    // 3️⃣ Use `run` to schedule a function in the default queue
    //     (this will run immediately if no run‑loop is active,
    //     otherwise it will be queued).
    this.get('run').schedule('sync', this, this.performHeavyWork);
  }

  performHeavyWork() {
    // Heavy computation here
    console.log('Heavy work performed');
  }
}
```

