// Example: Using Ember's RunLoop to defer DOM updates and schedule work

import Ember from 'ember';

export default Ember.Component.extend({
  // Trigger a run loop when the component is inserted into the DOM
  didInsertElement() {
    // 1. Immediate work inside the current run loop
    Ember.run(() => {
      console.log('Immediate work in the current run loop');
    });

    // 2. Schedule work to happen after the current run loop finishes
    Ember.run.scheduleOnce('afterRender', this, function() {
      console.log('This runs after the DOM has been updated');
      // DOM updates are guaranteed to be complete here
    });

    // 3. Schedule work to happen in the next run loop cycle
    Ember.run.scheduleOnce('actions', this, function() {
      console.log('This runs in the next run loop cycle');
    });

    // 4. Manually start a new run loop (rarely needed)
    Ember.run(() => {
      console.log('Manual run loop started');
      // Any work here will be batched together
    });
  },

  actions: {
    // Example action that triggers a run loop
    doSomething() {
      Ember.run(() => {
        console.log('Action triggered a run loop');
        // Perform state changes that will be batched
      });
    }
  }
});
