```js
// app/controllers/index.js
import Controller from '@ember/controller';
import { tracked } from '@glimmer/tracking';
import { task, timeout } from 'ember-concurrency';

export default class IndexController extends Controller {
  @tracked page = 1;
  @tracked loading = false;
  @tracked hasMore = true;

  @task
  *loadMore() {
    if (this.loading || !this.hasMore) { return; }

    this.loading = true;
    this.page += 1;

    try {
      const newPosts = yield this.store.query('post', {
        page: this.page,
        per_page: 20
      });

      // Ember Data will automatically merge the new records into the
      // existing array returned by the initial query.
      if (newPosts.length < 20) {
        this.hasMore = false; // no more pages
      }
    } finally {
      this.loading = false;
    }
  }

  // Debounce the scroll handler so we don't fire too often
  @task
  *debouncedLoadMore() {
    yield timeout(200);
    this.loadMore.perform();
  }
}
```

```js
// app/components/infinite-scroll.js
import Component from '@glimmer/component';
import { action } from '@ember/object';
import { inject as service } from '@ember/service';

export default class InfiniteScrollComponent extends Component {
  @service controller;

  @action
  handleScroll(event) {
    const { scrollTop, scrollHeight, clientHeight } = event.target;
    // If we are within 200px of the bottom, trigger loadMore
    if (scrollHeight - scrollTop - clientHeight < 200) {
      this.controller.debouncedLoadMore.perform();
    }
  }
}
```

```hbs
