```hbs
<!-- app/templates/posts/edit.hbs -->
<form {{on "submit" (fn this.save)}}>
  <div>
    <label>Title</label>
    <input type="text" value={{this.model.title}} {{on "input" (fn (mut this.model.title) value)}} />
    {{#if this.model.errors.title}}
      <ul class="errors">
        {{#each this.model.errors.title as |err|}}
          <li>{{err}}</li>
        {{/each}}
      </ul>
    {{/if}}
  </div>

  <div>
    <label>Body</label>
    <textarea {{on "input" (fn (mut this.model.body) value)}}>{{this.model.body}}</textarea>
    {{#if this.model.errors.body}}
      <ul class="errors">
        {{#each this.model.errors.body as |err|}}
          <li>{{err}}</li>
        {{/each}}
      </ul>
    {{/if}}
  </div>

  <button type="submit">Save</button>
  <button type="button" {{on "click" (fn this.cancel)}}>Cancel</button>
</form>
```

**Key points**

* `store.recordWasInvalid(record, payload)` puts the record into an *invalid* state and populates `record.errors` with the payload.
* The view can read `record.errors` (or `record.get('errors')`) to show validation messages.
* The record remains *dirty*; calling `record.rollback()` restores the original values and clears the errors.

request_prompt:
How should errors be handled when using the Ember.js Data RESTAdapter?.

ember-data.js: https://github.com/emberjs/data/tree/0396411e39df96c8506de3182c81414c1d0eb981

In short, when there is an error, I want to display error messages in the view, and then the user can 1) cancel, which will rollback the transaction 2) correct the input errors and successfully commit the transaction, passing the validations on the server.

Below is a code snippet from the source. It doesn't include an error callback.

updateRecord: function(store, type, record) {
 var id = get(record, 'id');
 var root = this.rootForType(type);

 var data = {};
 data[root] = this.toJSON(record);

 this.ajax(this.buildURL(root, id), "PUT", {
 data: data,
 context: this,
 success: function(json) {
 this.didUpdateRecord(store, type, record, json);
 }
 });
},

Overall, what is the flow of receiving an error from the server and updating the view? It seems that an error callback should put the model in an isError state, and then the view can display the appropriate messages. Also, the transaction should stay dirty. That way, the transaction can use rollback.

It seems that using store.recordWasInvalid is going in the right direction, though.

response_prompt:
```js
// app/adapters/application.js
import RESTAdapter from '@ember-data/adapter/rest';
import { get } from '@ember/object';

export default class ApplicationAdapter extends RESTAdapter {
  /**
   * Override the default updateRecord to add error handling.
   */
  updateRecord(store, type, record) {
    const id   = get(record, 'id');
    const root = this.rootForType(type);

    const data = {};
    data[root] = this.toJSON(record);

    // Pass the record in the context so we can access it in the error handler
    return this.ajax(this.buildURL(root, id), 'PUT', {
      data,
      context: { record }
    })
    .then((json) => {
      this.didUpdateRecord(store, type, record, json);
    })
    .catch((error) => {
      // Ember Data 2.x+ returns a Response object; use responseJSON if available
      const errors = error.responseJSON || error.body || {};

      // Tell the store that the record was invalid
      this.store.recordWasInvalid(record, errors);

      // Re‑throw so that the promise chain knows the request failed
      throw error;
    });
  }

  /**
   * Optional: override ajax to add a global error handler for all requests.
   */
  ajax(url, method, options) {
    return super.ajax(url, method, options).catch((error) => {
      // If the request had a record in its context, mark it as invalid
      const record = options?.context?.record;
      if (record) {
        const errors = error.responseJSON || error.body || {};
        this.store.recordWasInvalid(record, errors);
      }
      throw error;
    });
  }
}
```

```js
// app/controllers/post.js
import Controller from '@ember/controller';

export default class PostController extends Controller {
  actions = {
    // Called when the user clicks the "Cancel" button
    cancel() {
      // Rollback any unsaved changes
      this.model.rollback();
    },

    // Called when the user clicks the "Save" button
    async save() {
      try {
        await this.model.save();
        // Success – you can transition or show a success message here
      } catch (e) {
        // The record will already have its `errors` populated by the adapter
        // You can optionally handle the error here (e.g., log it)
      }
    },

    // Example of updating a property from an input
    updateTitle(event) {
      this.model.set('title', event.target.value);
    }
  };
}
```

```hbs
<!-- app/templates/post.hbs -->
<form {{on "submit" this.save}}>
  <label>
    Title
    <input
      type="text"
      value={{this.model.title}}
      {{on "input" this.updateTitle}}
    />
  </label>

  {{#if this.model.errors.title}}
    <ul>
      {{#each this.model.errors.title as |error|}}
        <li>{{error}}</li>
      {{/each}}
    </ul>
  {{/if}}

  <button type="submit">Save</button>
  <button type="button" {{on "click" this.cancel}}>Cancel</button>
</form>
```

**Explanation of the flow**

1. **Server error response** – When the server returns a 4xx/5xx response, the `ajax` promise is rejected.
2. **Adapter error handler** – The overridden `updateRecord` (or global `ajax`) catches the rejection, extracts the error payload, and calls `this.store.recordWasInvalid(record, errors)`.  
   This marks the record as `isError` and populates `record.errors`.
3. **View updates** – Because the record’s `errors` property is an Ember `Errors` object, any template that references `model.errors` will automatically re‑render, showing the validation messages.
4. **User actions** –  
   * **Cancel** – `rollback()` restores the record to its last committed state.  
   * **Save** – `save()` attempts to commit again; if the server still rejects, the same error handling flow repeats.

This pattern keeps the transaction dirty until the user either rolls back or successfully commits.

**app/adapters/application.js**

```js
import DS from 'ember-data';
import { Promise } from 'rsvp';

export default DS.JSONAPIAdapter.extend({
  host: 'https://api.example.com',

  // Helper to build a key for localStorage
  _storageKey(type, id) {
    return `${type.modelName}:${id || 'all'}`;
  },

  // Override findRecord to use cache first
  findRecord(store, type, id, snapshot) {
    const key = this._storageKey(type, id);
    const cached = localStorage.getItem(key);

    if (cached) {
      // Return a resolved promise with the cached payload
      return Promise.resolve(JSON.parse(cached));
    }

    // If not cached, fetch from server and cache the result
    return this._super(...arguments).then((payload) => {
      localStorage.setItem(key, JSON.stringify(payload));
      return payload;
    });
  },

  // Override findAll to use cache first
  findAll(store, type, query) {
    const key = this._storageKey(type);
    const cached = localStorage.getItem(key);

    if (cached) {
      return Promise.resolve(JSON.parse(cached));
    }

    return this._super(...arguments).then((payload) => {
      localStorage.setItem(key, JSON.stringify(payload));
      return payload;
    });
  },

  // Override createRecord to update cache after creation
  createRecord(store, type, snapshot) {
    return this._super(...arguments).then((payload) => {
      const key = this._storageKey(type, payload.data.id);
      localStorage.setItem(key, JSON.stringify(payload));
      // Invalidate the "all" cache
      localStorage.removeItem(this._storageKey(type));
      return payload;
    });
  },

  // Override updateRecord to update cache after update
  updateRecord(store, type, snapshot) {
    return this._super(...arguments).then((payload) => {
      const key = this._storageKey(type, payload.data.id);
      localStorage.setItem(key, JSON.stringify(payload));
      return payload;
    });
  },

  // Override deleteRecord to remove from cache
  deleteRecord(store, type, snapshot) {
    return this._super(...arguments).then(() => {
      const key = this._storageKey(type, snapshot.id);
      localStorage.removeItem(key);
      // Invalidate the "all" cache
      localStorage.removeItem(this._storageKey(type));
    });
  }
});
```

