import Service from '@ember/service';
import { inject as service } from '@ember/service';
import { later, cancel } from '@ember/runloop';

export default Service.extend({
  store: service(),

  // Poll interval in milliseconds
  pollInterval: 5 * 60 * 1000, // 5 minutes

  init() {
    this._super(...arguments);
    this._startPolling();
  },

  // Start polling for updates
  _startPolling() {
    this._poll();
  },

  // Poll once
  _poll() {
    // Example: fetch all posts from server
    this.get('store').findAll('post').then((payload) => {
      // The adapter already caches the payload
      // You can add extra logic here if needed
    }).finally(() => {
      // Schedule next poll
      this._pollTimer = later(this, this._poll, this.get('pollInterval'));
    });
  },

  // Stop polling when service is destroyed
  willDestroy() {
    cancel(this._pollTimer);
    this._super(...arguments);
  }
});
