```js
// app/adapters/application.js
import JSONAPIAdapter from '@ember-data/adapter/json-api';
import { inject as service } from '@ember/service';

export default class ApplicationAdapter extends JSONAPIAdapter {
  @service syncService;

  async findRecord(store, type, id, snapshot) {
    const cached = this.syncService.getFromCache(type.modelName, id);
    if (cached) {
      return store.push(cached);
    }
    const record = await super.findRecord(store, type, id, snapshot);
    this.syncService.setToCache(type.modelName, id, record);
    return record;
  }

  async createRecord(store, type, snapshot) {
    const record = await super.createRecord(store, type, snapshot);
    this.syncService.setToCache(type.modelName, record.id, record);
    return record;
  }

  async updateRecord(store, type, snapshot) {
    const record = await super.updateRecord(store, type, snapshot);
    this.syncService.setToCache(type.modelName, record.id, record);
    return record;
  }

  async deleteRecord(store, type, snapshot) {
    const record = await super.deleteRecord(store, type, snapshot);
    this.syncService.removeFromCache(type.modelName, snapshot.id);
    return record;
  }
}
```

```js
// app/services/sync-service.js
import Service from '@ember/service';

export default class SyncService extends Service {
  cache = new Map();

  _key(modelName, id) {
    return `${modelName}:${id}`;
  }

  getFromCache(modelName, id) {
    const key = this._key(modelName, id);
    const data = this.cache.get(key);
    if (!data) { return null; }
    return this._deserialize(data);
  }

  setToCache(modelName, id, record) {
    const key = this._key(modelName, id);
    const data = this._serialize(record);
    this.cache.set(key, data);
    localStorage.setItem(key, JSON.stringify(data));
  }

  removeFromCache(modelName, id) {
    const key = this._key(modelName, id);
    this.cache.delete(key);
    localStorage.removeItem(key);
  }

  _serialize(record) {
    const json = record.serialize();
    json.id = record.id;
    return json;
  }

  _deserialize(data) {
    const store = this.owner.lookup('service:store');
    const type = store.modelFor(data.type);
    return store.push({ data: { type: data.type, id: data.id, attributes: data } });
  }

  loadCache() {
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      const value = localStorage.getItem(key);
      const data = JSON.parse(value);
      this.cache.set(key, data);
    }
  }
}
