// app/serializers/application.js
import DS from 'ember-data';

export default DS.JSONAPISerializer.extend({
  extractErrors(store, type, payload, id, requestType) {
    const errors = payload.errors || [];
    const errorMap = {};

    errors.forEach(err => {
      const source = err.source || {};
      const pointer = source.pointer || '';
      // pointer format: /data/attributes/attributeName
      const parts = pointer.split('/');
      if (parts.length >= 4 && parts[1] === 'data' && parts[2] === 'attributes') {
        const attr = parts[3];
        errorMap[attr] = errorMap[attr] || [];
        errorMap[attr].push(err.title || err.detail || err.message);
      }
    });

    return { errors: errorMap };
  }
});
