```js
// Polars 0.20+ – no `orient` argument, but you can build the same
// “records” list of dictionaries that pandas gives with `orient='records'`.

import * as pl from '@polars/polars';

// your dataframe
const df = pl.DataFrame({
  column_1: [1, 2, 1, 4, 5],
  column_2: ['Alice', 'Bob', 'Alice', 'Tom', 'Tom'],
  column_3: ['Alice1', 'Bob', 'Alice2', 'Tom', 'Tom'],
});

// 1. Convert the dataframe to a dict of column‑wise lists
const colDict = df.to_dict({ as_series: false });   // {column_1: [...], …}

// 2. Zip the column lists together to get rows
const rows = Object.values(colDict).reduce(
  (acc, col) => acc.map((row, i) => [...row, col[i]]),
  [[]]
);

// 3. Attach the column names to each row
const records = rows.map(row => {
  const obj = {};
  df.columns.forEach((c, i) => (obj[c] = row[i]));
  return obj;
});

console.log(records);
/*
[
  { column_1: 1, column_2: 'Alice', column_3: 'Alice1' },
  { column_1: 2, column_2: 'Bob',   column_3: 'Bob'   },
  { column_1: 1, column_2: 'Alice', column_3: 'Alice2' },
  { column_1: 4, column_2: 'Tom',   column_3: 'Tom'   },
  { column_1: 5, column_2: 'Tom',   column_3: 'Tom'   }
]
*/
```

**Explanation**

* `df.to_dict({ as_series: false })` gives a plain JavaScript object where each key is a column name and the value is an array of that column’s values.
* By zipping those arrays together we reconstruct the rows.
* Finally we pair each row with the column names to produce the list of dictionaries that matches pandas’ `orient='records'` output.

