```js
// Example: calculate month start and end dates for an array of ISO‑8601 strings
const dates = ['2022-02-13', '2023-02-13', '2024-01-01'];

/**
 * Returns the first day of the month for a given date string.
 * @param {string} isoDate - ISO‑8601 date string (YYYY-MM-DD)
 * @returns {string} ISO‑8601 string of the month start (YYYY-MM-01)
 */
function monthStart(isoDate) {
  const d = new Date(isoDate);
  d.setDate(1);                 // set to first day of month
  d.setHours(0, 0, 0, 0);       // normalize time
  return d.toISOString().slice(0, 10);
}

/**
 * Returns the last day of the month for a given date string.
 * @param {string} isoDate - ISO‑8601 date string (YYYY-MM-DD)
 * @returns {string} ISO‑8601 string of the month end (YYYY-MM-DD)
 */
function monthEnd(isoDate) {
  const d = new Date(isoDate);
  // Move to the first day of the next month
  d.setMonth(d.getMonth() + 1);
  d.setDate(1);
  // Subtract one day to get the last day of the original month
  d.setDate(d.getDate() - 1);
  d.setHours(0, 0, 0, 0);
  return d.toISOString().slice(0, 10);
}

// Build a new array with the original date, month start and month end
const result = dates.map(date => ({
  original: date,
  monthStart: monthStart(date),
  monthEnd: monthEnd(date)
}));

console.log(result);

/*
Output:
[
  { original: '2022-02-13', monthStart: '2022-02-01', monthEnd: '2022-02-28' },
  { original: '2023-02-13', monthStart: '2023-02-01', monthEnd: '2023-02-28' },
  { original: '2024-01-01', monthStart: '2024-01-01', monthEnd: '2024-01-31' }
]
*/
```

**Explanation**

1. `monthStart` sets the day of the month to `1` and normalises the time to midnight, then formats the date back to `YYYY-MM-DD`.
2. `monthEnd` moves the date to the first day of the next month, subtracts one day, and formats it similarly.
3. The example maps over an array of date strings, producing an object that contains the original date, the month start, and the month end.

This solution uses only JavaScript’s built‑in `Date` object, so no external npm packages are required.

