// ------------------------------------------------------------
// 1.  Install dependencies
// ------------------------------------------------------------
// npm install mongoose milvus-client-nodejs @tensorflow/tfjs-node
// ------------------------------------------------------------

// 2.  Mongoose schema – store metadata + embedding vector
const mongoose = require('mongoose');
const { Schema } = mongoose;

const mediaSchema = new Schema({
  title: String,
  type: { type: String, enum: ['text', 'image', 'video'] },
  content: String,          // raw text / image URL / video URL
  embedding: [Number],      // vector stored in MongoDB for backup
  createdAt: { type: Date, default: Date.now }
});

const Media = mongoose.model('Media', mediaSchema);

// 3.  Milvus client – vector index
const { MilvusClient, DataType } = require('milvus-client-nodejs');
const milvus = new MilvusClient('localhost:19530'); // Milvus running locally

async function initMilvus() {
  const collectionName = 'media_vectors';
  const has = await milvus.hasCollection({ collection_name: collectionName });
  if (!has.has_collection) {
    await milvus.createCollection({
      collection_name: collectionName,
      fields: [
        { name: 'id', type: DataType.Int64, is_primary_key: true, auto_id: true },
        { name: 'embedding', type: DataType.FloatVector, dim: 512 }
      ]
    });
  }
}
await initMilvus();

// 4.  Dummy embedding function (replace with real model)
async function getEmbedding(text) {
  // Example: random 512‑dim vector
  return Array.from({ length: 512 }, () => Math.random());
}

// 5.  Insert media + vector
async function addMedia({ title, type, content }) {
  const embedding = await getEmbedding(content);
  const doc = await Media.create({ title, type, content, embedding });

  // Insert into Milvus
  await milvus.insert({
    collection_name: 'media_vectors',
    fields_data: [
      {
        id: doc._id.toString(),
        embedding
      }
    ]
  });
  return doc;
}

// 6.  Vector search
async function search(queryText, topK = 5) {
  const queryVec = await getEmbedding(queryText);
  const res = await milvus.search({
    collection_name: 'media_vectors',
    anns_field: 'embedding',
    topk: topK,
    vector: queryVec,
    params: { nprobe: 10 }
  });

  // Map Milvus results back to MongoDB docs
  const ids = res.ids.map(id => mongoose.Types.ObjectId(id));
  const docs = await Media.find({ _id: { $in: ids } });
  return docs;
}

// 7.  Example usage
(async () => {
  await mongoose.connect('mongodb://localhost:27017/media_db');

  // Add a sample media item
  await addMedia({
    title: 'Sample Image',
    type: 'image',
    content: 'https://example.com/image.jpg'
  });

  // Perform a search
  const results = await search('beautiful landscape');
  console.log('Search results:', results);

  await mongoose.disconnect();
})();
