response_prompt:
`next-auth` only puts a few fields into the session by default.  
When you use the **jwt** strategy the data that comes from `authorize()` is
stored in the JWT token, and the session callback decides which of those
fields are exposed to the client.

Add a `callbacks` section (or modify the existing one) so that the
properties you need are copied from the token into the session.  
Also return a plain JavaScript object from `authorize()` – a Mongoose
document contains many internal fields that are stripped out.

```ts
// [...nextauth].ts
import NextAuth from "next-auth";
import CredentialsProvider from "next-auth/providers/credentials";
import { connectToDb } from "@utils/database";
import User from "@models/user";
import bcrypt from "bcrypt";

export const authOptions = {
  providers: [
    CredentialsProvider({
      name: "credentials",
      credentials: {
        email: { label: "Email", type: "email", placeholder: "" },
        password: { label: "Password", type: "password", placeholder: "" },
      },

      async authorize(credentials) {
        const { email, password } = credentials || {};

        try {
          await connectToDb();

          const user = await User.findOne({ email });
          if (!user) return null;

          const passwordsMatch = await bcrypt.compare(password, user.password);
          if (!passwordsMatch) return null;

          // Return a plain object (no Mongoose internals)
          return {
            id: user._id.toString(),
            email: user.email,
            firstName: user.firstName,
            lastName: user.lastName,
            phoneNumber: user.phoneNumber,
          };
        } catch (err) {
          console.error(err);
          return null;
        }
      },
    }),
  ],

  session: { strategy: "jwt" },

  callbacks: {
    // Called when a JWT is created or updated
    async jwt({ token, user }) {
      if (user) {
        token.id = user.id;
        token.email = user.email;
        token.firstName = user.firstName;
        token.lastName = user.lastName;
        token.phoneNumber = user.phoneNumber;
      }
      return token;
    },

    // Called when a session is created (client side)
    async session({ session, token }) {
      session.user = {
        id: token.id,
        email: token.email,
        firstName: token.firstName,
        lastName: token.lastName,
        phoneNumber: token.phoneNumber,
      };
      return session;
    },
  },

  secret: process.env.NEXTAUTH_SECRET,
  pages: { signIn: "/login" },
};

const handler = NextAuth(authOptions);
export { handler as GET, handler as POST };
```

Now in your dashboard you can access all the fields:

```tsx
'use client';
import { useSession } from "next-auth/react";

export default function DashboardPage() {
  const { data: session, status } = useSession();

  console.log("dashboard", session);

  return (
    <div>
      <h1>Dashboard</h1>
      {session?.user?.email}
      <p>First: {session?.user?.firstName}</p>
      <p>Last: {session?.user?.lastName}</p>
      <p>Phone: {session?.user?.phoneNumber}</p>
    </div>
  );
}
```

With the callbacks in place, the session now contains the full user
profile instead of just the email.

rag_response:
`next‑auth` only puts a **very small** user object into the session by default.  
When you return a user from `authorize()` the library stores that user in the
JWT token, but the `session` callback (which is run every time the client
calls `useSession`) only copies the fields that are explicitly added to the
token.  
Because you didn’t add any custom fields, the session that the client sees
contains only the `email`.

Add a `callbacks` section (or switch to the database session strategy) and
copy the fields you need from the token into the session.

```ts
// pages/api/auth/[...nextauth].ts
import NextAuth from "next-auth";
import CredentialsProvider from "next-auth/providers/credentials";
import { connectToDb } from "@utils/database";
import User from "@models/user";
import bcrypt from "bcrypt";

export const authOptions = {
  providers: [
    CredentialsProvider({
      name: "credentials",
      credentials: {
        email: { label: "Email", type: "email", placeholder: "" },
        password: { label: "Password", type: "password", placeholder: "" },
      },

      async authorize(credentials) {
        const { email, password } = credentials || {};

        try {
          await connectToDb();

          const user = await User.findOne({ email });
          if (!user) return null;

          const passwordsMatch = await bcrypt.compare(password, user.password);
          if (!passwordsMatch) return null;

          // Return the whole user document (except the password)
          const { password: _, ...rest } = user.toObject();
          return rest;
        } catch (err) {
          console.error(err);
          return null;
        }
      },
    }),
  ],

  // Use JWT sessions
  session: { strategy: "jwt" },

  // Add callbacks to expose custom fields
  callbacks: {
    // Called whenever a JWT is created or updated
    async jwt({ token, user }) {
      if (user) {
        // Persist the fields you want in the token
        token.id = user._id;
        token.firstName = user.firstName;
        token.lastName = user.lastName;
        token.phoneNumber = user.phoneNumber;
        // …add any other fields you need
      }
      return token;
    },

    // Called when the session is returned to the client
    async session({ session, token }) {
      // Attach the token fields to the session.user object
      session.user.id = token.id;
      session.user.firstName = token.firstName;
      session.user.lastName = token.lastName;
      session.user.phoneNumber = token.phoneNumber;
      // …add any other fields you added to the token
      return session;
    },
  },

  secret: process.env.NEXTAUTH_SECRET,
  pages: { signIn: "/login" },
};

const handler = NextAuth(authOptions);
export { handler as GET, handler as POST };
```

Now in your dashboard:

```tsx
'use client';
import { useSession } from "next-auth/react";

export default function DashboardPage() {
  const { data: session, status } = useSession();

  console.log("dashboard", session); // will show all the fields you added

  return (
    <div>
      <h1>Dashboard</h1>
      <p>{session?.user?.email}</p>
      <p>{session?.user?.firstName}</p>
      <p>{session?.user?.lastName}</p>
      {/* …etc */}
    </div>
  );
}
```

**Key points**

* The default session only contains `name`, `email`, and `image`.
* Use the `jwt` and `session` callbacks to copy any additional user data
  into the session.
* Never expose sensitive data (e.g., the password) in the session.

