```ts
// server/api/loader.ts
import { defineEventHandler, readMultipartFormData, getRequestHeader } from '#imports'
import { InnoDB } from 'inno-db'

export default defineEventHandler(async (event) => {
  // Parse the multipart body
  const form = await readMultipartFormData(event)

  // The file field is named "userFile"
  const file = form.files?.userFile
  if (!file) throw createError({ statusCode: 400, statusMessage: 'No file uploaded' })

  // file.data is a Buffer containing the file contents
  const fileBuffer: Buffer = file.data

  const fileName = getRequestHeader(event, 'fileName') ?? file.name
  const fileType = getRequestHeader(event, 'fileType') ?? file.type
  const fileTTL  = getRequestHeader(event, 'fileTTL') ?? 0

  const dbFileInstance = new InnoDB({
    id: InnoDB.autoGenerate,
    File: fileBuffer,
    FileName: fileName,
    'Content-Type': fileType,
    TTL: fileTTL
  })

  await new Promise((resolve, reject) => {
    dbFileInstance.save((doc, err) => {
      if (err) reject(err)
      else resolve(doc)
    })
  })

  return { status: 200, message: 'File stored' }
})
```

**Key points**

1. **Do not set `Content-Type` manually** – the browser will add the correct multipart boundary.
2. Use `readMultipartFormData(event)` to get an object with `fields` and `files`.
3. Each file entry has a `data` property that is a `Buffer` (or `Blob` in the browser). Use that buffer to store the file.

