```js
// ──────────────────────────────────────────────────────────────────────
//  Client – create the request (no manual Content‑Type header)
// ──────────────────────────────────────────────────────────────────────
export function createFormData(file) {
  const formData = new FormData()
  formData.append('userFile', file, file.name)   // field name = "userFile"
  return formData
}

export async function uploadFile(file) {
  const formData = createFormData(file)

  const response = await fetch('/data/file/api/loader', {
    method: 'POST',
    body: formData          // browser will set the correct multipart boundary
  })

  return { status: response.status }
}
```

```js
// ──────────────────────────────────────────────────────────────────────
//  Server – Nuxt 3 handler (server/api/loader.ts)
// ──────────────────────────────────────────────────────────────────────
import { defineEventHandler, readMultipartFormData, getRequestHeader } from '#imports'
import { InnoDB } from 'inno-db'

export default defineEventHandler(async (event) => {
  // 1️⃣  Parse the multipart/form-data payload
  const form = await readMultipartFormData(event)

  // 2️⃣  Grab the uploaded file (field name = "userFile")
  const uploadedFile = form.files?.userFile
  if (!uploadedFile) {
    throw createError({ statusCode: 400, statusMessage: 'No file uploaded' })
  }

  // 3️⃣  The file data is already a Buffer (Node.js Buffer)
  const fileBuffer = uploadedFile.data

  // 4️⃣  Optional: read any custom headers you sent
  const fileName = getRequestHeader(event, 'fileName') || uploadedFile.name
  const fileType = getRequestHeader(event, 'fileType') || uploadedFile.type
  const fileTTL  = getRequestHeader(event, 'fileTTL')  || 0

  // 5️⃣  Store the file in the proprietary database
  const dbFileInstance = new InnoDB({
    id: InnoDB.autoGenerate,
    File: fileBuffer,          // Buffer
    FileName: fileName,
    'Content-Type': fileType,
    TTL: fileTTL
  })

  await new Promise((resolve, reject) => {
    dbFileInstance.save((doc, err) => {
      if (err) return reject(err)
      resolve(doc)
    })
  })

  return { success: true }
})
```

### Key points

1. **Do not set `Content-Type` manually** – the browser will add the correct `multipart/form-data; boundary=…` header when you pass a `FormData` instance as the request body.
2. **Use `readMultipartFormData(event)`** – this parses the multipart payload and returns an object with `fields` and `files`.  
   Each file entry has a `data` property that is a Node.js `Buffer`.
3. The `fileBuffer` can be passed directly to your database API that expects a `Buffer`, `Blob`, or `ArrayBuffer`. If you need an `ArrayBuffer`, simply call `fileBuffer.buffer` or `Buffer.from(fileBuffer)`.

This pattern works for any file type (Excel, PDF, images, etc.) and keeps the client‑side code minimal.

