import Component from '@ember/component';
import { action } from '@ember/object';

export default class BaseComponent extends Component {
  // Called when the component is inserted into the DOM
  didInsertElement() {
    this._clickHandler = this._handleClick.bind(this);
    this.element.addEventListener('click', this._clickHandler);
  }

  // Called just before the component is removed from the DOM
  willDestroyElement() {
    this.element.removeEventListener('click', this._clickHandler);
    this._clickHandler = null;
  }

  // Generic click handler that looks for the `trackClick` attribute
  _handleClick(event) {
    // Find the closest ancestor (or self) that has the attribute
    const target = event.target.closest('[trackClick]');
    if (!target) { return; }

    // Grab the value of the attribute
    const value = target.getAttribute('trackClick');

    // If the component defines an `elementClicked` method, call it
    if (typeof this.elementClicked === 'function') {
      this.elementClicked(value);
    }
  }
}
```

