async function getSubset() {
  // Streaming train split
  const trainStream = await loadDataset(
    'MLCommons/peoples_speech',
    'clean',
    { split: 'train', streaming: true, downloadConfig }
  );

  // Take the first 10 000 rows (adjust as needed)
  const trainSubset = trainStream.take(10000).toDataset();

  // Streaming test split
  const testStream = await loadDataset(
    'MLCommons/peoples_speech',
    'clean',
    { split: 'test', streaming: true, downloadConfig }
  );

  const testSubset = testStream.take(10000).toDataset();

  return { trainSubset, testSubset };
}

getSubset().then(({ trainSubset, testSubset }) => {
